INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Assassin''s Creed II: Black Edition', 'A limited edition available in parts of Europe and Australia. It included: • "Master Assassin" Ezio Auditore da Firenze upgrade figurine with black collector''s box. • 3 in-game bonus missions, allowing Ezio to explore the following: Palazzo Medici in Florence, Santa Maria dei Frari in Venice, and Arsenal Shipyard in Venice. • "Conspiracy book": A book from the developers of the game, describing the development and the storyline (with extra commentary on the "conspiracy"). 64 pages, hardcover, "leather style". • DVD with all the videos, behind-the-scene interviews and "e-goodies" about Assassin''s Creed II, and game soundtrack by Jesper Kyd (BAFTA nominee for "2009 Best Original Score in a Game"). • Black packaging with unique holographic signature.' FROM games WHERE igdb_id = 308958 ON CONFLICT (game_id, language_code) DO NOTHING;
