INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dream Dance & Cheer', 'Grab your Pom-Poms and get out on the field! Play as Hanna, a young cheerleader who dreams of making it in the professional cheering world. Show your best dance moves using your Wii Balance Board for the most realistic cheering experience yet. Or compete with a friend for ultimate bragging rights. You''ll be a pro in no time in Dream Dance & Cheer! Features • Dance and cheer in 20 events spread out over several stadiums and arenas• Unlock and customize cheerleading outfits, pom-poms, and shoes• Gold, Silver, and Bronze medals are given out after each performance allowing the player to unlock new stadiums, outfits, and accessories• Play along in Story Mode or compete with a friend head-to-head in a Cheer Battle' FROM games WHERE igdb_id = 50632 ON CONFLICT (game_id, language_code) DO NOTHING;
