INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dream Chronicles: The Chosen Child', 'Unlock the secrets of the beautiful and mysterious fairy realm in the third installment of the award-winning Dream Chronicles series. Discover hidden clues and solve challenging puzzles as you join Faye on her quest to save her daughter from the clutches of the Fairy Queen Lilith with the assistance of her husband Fidget. Reveal the secret prophecy of The Chosen Child as you unlock the Nexus to solve puzzles that span across multiple areas and immerse yourself in this all-new hunt-and-seek adventure with unexpected twists that will keep you searching for answers throughout the game.' FROM games WHERE igdb_id = 16071 ON CONFLICT (game_id, language_code) DO NOTHING;
