INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Family Party: 30 Great Games', 'Family Party for Wii gives you 30 reasons to celebrate with 30 Great Games everyone can enjoy! Pick from 12 playable characters and frolic through a vibrant and colorful world you can''t help but enjoy. Test your speed and athletic skill in hurdles and sprints, on an obstacle course, and in the high jump. Take aim in carnival games that use lasers and bows and arrows. Show off your strength in barrel tossing, rope climbing, and log tossing. Hit the playground for schoolyard fun with jump rope, a game of catch, and more. Multiple game modes offer turn-based and all-together play for one to four players.' FROM games WHERE igdb_id = 50964 ON CONFLICT (game_id, language_code) DO NOTHING;
