INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek Newton: Part One - Anomaly', 'Crewman John Fischer is a recent graduate of Starfleet Academy assigned to the USS Newton, a Constitution-class vessel currently tasked with performing scientific surveys in Sector 004. On the completion of his first week aboard his new assignment, John begins to realize that the reality of life in Starfleet isn''t all chasing hostile aliens and meeting strange cultures. In fact, it can be quite dull. No sooner does he log this gloomy summary than the ship is rattled by some unseen force that disables many of the ships systems! Isolated and unaware of what is wreaking havoc on the Newton, John must get to his duty station and help himself and his crew stabilize the ship.' FROM games WHERE igdb_id = 171782 ON CONFLICT (game_id, language_code) DO NOTHING;
