INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spider-Sense Spider-Man and the Masked Menace', 'Spider-Sense Spider-Man and the Masked Menace is a Plug It In & Play TV game controller based on Spider-Man. The game is a platforming side-scroller with nine levels. The first two levels have you track down the Spider-Man imposter and fight him on the second level. Doctor Octopus is the Masked Menace' FROM games WHERE igdb_id = 220110 ON CONFLICT (game_id, language_code) DO NOTHING;
