INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unwell Mel', 'The doctor is in, with this madcap Match 3 game! Poor Mel has every ailment in the book, and you`re the only one who can cure him. Use your scanner to figure out what’s got him this time, whether it`s too much junk food, or some zany virus, and get to work. Make matching sets of medicines to dispel Mel`s blues and bring him back to good health. Buy special remedies, like Big Fish Oil to aid your efforts. Help Mel get well now!' FROM games WHERE igdb_id = 16181 ON CONFLICT (game_id, language_code) DO NOTHING;
