INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-Gi-Oh! Online 3: Duel Accelerator', 'Yu-Gi-Oh! Online 3: Duel Accelerator was the last update of the Yu-Gi-Oh! Online series, and it added more cards along with many characters from the Yu-Gi-Oh! 5D''s anime series. Yu-Gi-Oh! servers closed on September 30, 2012 at 19:00 EST (October 1, 2012 at 02:00 GMT), due to an internal decision by Konami not to support the service beyond that date.' FROM games WHERE igdb_id = 78166 ON CONFLICT (game_id, language_code) DO NOTHING;
