INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toki Hako Time Capsule', 'A summer vacation day. Main heroine digs up a time capsule buried as a child with two friends. Surprisingly, there is also a fourth person belongings inside the capsule, and none of the three friends have any recollections of that person. They start investigation to find out the shocking truth.' FROM games WHERE igdb_id = 342767 ON CONFLICT (game_id, language_code) DO NOTHING;
