INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asterz', 'Asterz is a shoot-em-up space game partly inspired by the classic shooter Asteroids, originally released in 1979 by Atari. This homebrew is made by Team Duck Production, with a unqiue combination of utilizing 3D rendering and 2D object. It was submitted to the NEO Spring Coding Compo 2009 (PSP Game, 2nd place).' FROM games WHERE igdb_id = 343141 ON CONFLICT (game_id, language_code) DO NOTHING;
