INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Compare the Meerkat', 'Internet toy made to tie in with a comedic marketing campaign, where Russian meerkats would complain about being confused for the subject of the campaign, Compare the Market - a price comparison site, in contrast to their business of contrasting meerkats against one another. UK version was delisted long ago, and is non-functional on WayBack Machine, but the game remains on the Australian site.' FROM games WHERE igdb_id = 313280 ON CONFLICT (game_id, language_code) DO NOTHING;
