INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hello Kitty Party', 'More than 25 different easy-to-pick-up-and-play mini-games starring Hello Kitty and her Sanrio friends: Keroppi, Badtz-Maru, My Melody and more Have a Party: Send out personalized invitations to any of Hello Kitty''s friends Dress Making: Sew, iron, cut patterns, and play the button, maze or material hoopla games Cooking: Satisfy your culinary appetite by cooking, slicing, frying, washing and even cleaning up, because every good party leaves a mess Dress up Hello Kitty in a variety of outfits and accessories (including jewelry, hats and handbags) and then take photos that can be saved to your album' FROM games WHERE igdb_id = 24342 ON CONFLICT (game_id, language_code) DO NOTHING;
