INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdom Hearts: Card Struggle - Spider Solitaire', 'Kingdom Hearts Card Struggle -Spider Solitaire- is a mini-game application available through Kingdom Hearts Mobile. It is a Kingdom Hearts-themed version of the card game Spider. Kingdom Hearts Card Struggle -Spider Solitaire- was released on January 22, 2009. It was discontinued on April 30, 2013 along with the rest of Kingdom Hearts Mobile.' FROM games WHERE igdb_id = 320421 ON CONFLICT (game_id, language_code) DO NOTHING;
