INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amagami', 'Amagami is a Japanese dating simulation game for the PlayStation 2 and the spiritual successor to KimiKiss. Two years ago, Junichi Tachibana had his heart broken by a girl who stood him up on a date on Christmas Eve. Now a second-year student in high school, Junichi is wary of love because of his past and dislikes celebrating Christmas. However this Christmas, his encounter with one of six girls from his school: Haruka Morishima, Kaoru Tanamachi, Sae Nakata, Ai Nanasaki, Rihoko Sakurai, or Tsukasa Ayatsuji will finally open his true self and heart.' FROM games WHERE igdb_id = 136599 ON CONFLICT (game_id, language_code) DO NOTHING;
