INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Runway', 'Enter the fast paced and exciting world of Runway. You start the game as the lead Air Traffic Controller at Honolulu International Airport. Help Gulfstream G650 aircraft land at your airport before they run out of fuel. Direct them to the gate to unload passengers and to the fuel depot to prepare for their outbound journey. Then it is time for more passengers and a timely takeoff.' FROM games WHERE igdb_id = 174345 ON CONFLICT (game_id, language_code) DO NOTHING;
