INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Trucks Mayhem', 'Strap yourself in because it''s time for some Monster Trucks Mayhem! Enormous tires, incredibly powerful engines, and the shocking excitement of monster truck racing has come exclusively to Wii! Put the beasts to the test as you tear through some of the meanest and most challenging tracks devised, destroying whatever lies in your path and smashing opponents off the road. Roaring, pumping engines! Destructively powerful tires! Stunning off-road experiences! All combine to bring the shocking excitement of Monster Trucks Mayhem home for play' FROM games WHERE igdb_id = 50718 ON CONFLICT (game_id, language_code) DO NOTHING;
