INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Merry Gear Solid 2: Ghosts of Christmas Past', 'Merry Gear Solid 2: The Ghosts of Christmas Past is a fan-game based on the Metal Gear series with a Christmas theme. 4 Set years after the events of the first game, Merry Gear Solid 2 sets Old Snake on an adventure to retrieve Santa’s Hat from an extremist group known as the Ghosts of Christmas Past. Using an array of new tools, and returning favorites, Solid Snake must infiltrate Outer Savin’ mall and prevent the Ghosts from taking control of the SOC (Spirit of Christmas) System.' FROM games WHERE igdb_id = 91648 ON CONFLICT (game_id, language_code) DO NOTHING;
