INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Manky', 'Manky is a single-screen platformer inspired by early 1980s games like Chuckie Egg and Manic Miner. The game follows Manky, who urgently needs the toilet, but it has been walled up. To reach it, he must collect keys and a set number of eggs laid by a roaming bird, while avoiding piles of grain that are fatal unless he eats an egg first. A timer adds pressure, and failure results in an unfortunate accident.' FROM games WHERE igdb_id = 336175 ON CONFLICT (game_id, language_code) DO NOTHING;
