INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'House Flip', 'Buy, fix, and sell houses with a click of your mouse in House Flip! Browse the listings, then purchase and inspect a house to see what needs fixing. Hold an open house to see which renovations prospective buyers want. Choose a section of the house to clean, repair, or upgrade, and then play mini-games to do the work yourself.' FROM games WHERE igdb_id = 281329 ON CONFLICT (game_id, language_code) DO NOTHING;
