INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Die Gilde DS', 'Die Gilde DS is a medieval economic simulation adapted for the Nintendo DS. Players inherit a family business and must build a powerful guild through trade, politics, and strategic decisions. The game features turn-based rounds, multiple victory paths (e.g., wealth, influence, or eliminating rivals), and various skills like rhetoric, commerce, and combat. It includes mini-games for negotiation and duels, and offers a static map with seasonal changes.' FROM games WHERE igdb_id = 81509 ON CONFLICT (game_id, language_code) DO NOTHING;
