INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('copter-crisis', 51123, '2009-11-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9pwz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/v9spx69mzv2uaabkqgmz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Copter Crisis', 'Copter Crisis puts you in the pilot’s seat! Copter Crisis puts you in the pilot’s seat! As a member of the elite Helicopter Rescue Squad, you’ll be assigned to respond to any type of emergency anywhere at anytime. As the newest member joining this team, you’ll have to complete various missions with the latest in helicopter rescue technology. When you’re ready, you’ll be tasked with executing rescue missions all around the Black Rock Canyon. Your Wii Remote controller becomes the control stick as you guide your copter along the canyons while avoiding rocks, severe weather and even anti-aircraft fire! Rescue lost hikers, deliver supplies to remote areas, assist on scientific missions and even blast your way into underground cavern systems. Complete all of your objectives and rise through the ranks to take on the toughest rescues and unlock 10 bonus missions. Nintendo Wi-Fi Connection Pay & Play allows you to enhance your flight experience with 10 additional copters. Unlimited missiles, larger fuel tanks, cargo holds and even mid-air loops!' FROM games WHERE igdb_id = 51123 ON CONFLICT (game_id, language_code) DO NOTHING;
