INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Build-A-Lot 3: Passport to Europe', 'Build-a-lot 3 is your passport to fun! Travel all over Europe as you restore rundown houses, develop friendly services and beautify neighborhoods with picturesque landmarks. The changing needs of the neighborhood will sure keep you busy--you may need to brave the rain and snow, deal with noisy neighbors, or even put out a small fire to get the job done on time! Pack your bags and let the fun take flight in the exciting sequel to Build-a-lot 1 & 2.' FROM games WHERE igdb_id = 16088 ON CONFLICT (game_id, language_code) DO NOTHING;
