INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guns n'' Angel', 'Guns n'' Angel is a flash game developed by Ninja Kiwi (which was formerly known as Kaiparasoft when this game was originally developed) and released on February 3, 2009. It''s an action platformer game where the player takes control of a gun-slinging girl named Angel who travels across the world to stop an invading alien army. Although Flash was discontinued on January 12 2021, Guns n'' Angel is still playable through BlueMaxima’s Flashpoint, The Supernova Player and The Ninja Kiwi Archive.' FROM games WHERE igdb_id = 287375 ON CONFLICT (game_id, language_code) DO NOTHING;
