INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Masters of Mystery: Crime of Fashion', 'The New York fashion world is turned upside down when detective Carrie Chase discovers that a famous fashion designer has been murdered. She soon comes to the frightening realization that a serial killer is at large with an eye for design and a thirst for murder. Masters of Mystery: Crime of Fashion is a thrilling hidden object game with an intriguing story, stunning environments and visual effects, unique investigative tools, and cunning puzzles.' FROM games WHERE igdb_id = 341071 ON CONFLICT (game_id, language_code) DO NOTHING;
