INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wizards of Waverly Place', 'Wizards of Waverly Place allows fans to play as their favourite wizard-in-training, Alex Russo, who is played by rising star Selena Gomez on the show, casting magical spells and participating in mini-games to complete tasks and acquire new magic skills. Players can experience the lives of the Russo kids as they explore locations from the show, including the Waverly Sub Station, the Wizards Lair, Tribeca Prep, the Russo loft and many more.' FROM games WHERE igdb_id = 44065 ON CONFLICT (game_id, language_code) DO NOTHING;
