INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-princess-and-the-rose-knight', 261059, '2009-09-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6x3a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scnve4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Princess and the Rose Knight', 'Short yuri-themed RPG Maker game created by rpgex/En. The player controls Galatea, commander of the newly established princess guard,on her adventures trying to protect the adventure-loving princess of Laomedia. The player must explore various dungeons and partake in turn-based combat to defeat enemies. While the in-dungeon gameplay is fairly similar to most traditional console RPGs (although, the game does feature a SaGa-inspired glimmer system for unlocking new abilities mid-combat), while in the castle, the player can also interact with a variety of characters and flirt with all the cute girls around! The game keeps track of how "yuri" the player''s responses to the different characters are via a yuri gauge, a fun play on the typical alignment gauge found in other RPGs.' FROM games WHERE igdb_id = 261059 ON CONFLICT (game_id, language_code) DO NOTHING;
