INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wandering Willows', 'Ready for a new adventure? Welcome to Wandering Willow, a whimsical world full of wondrous wildlife and engaging quests. With over forty enchanting pets for you to befriend and train, you''re sure to find just the right help completing quests for the land''s amusing inhabitants, who range from gruff pirates to rocket ship commanders. Garden, bake, and create clothing and bouquets with the treasures your pet fetches for you. You might even find a new pet egg to hatch! Spend some time in Wandering Willows today!' FROM games WHERE igdb_id = 16073 ON CONFLICT (game_id, language_code) DO NOTHING;
