INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fritz & Chesster: Chess for Aliens', 'This educational chess game takes place on an alien planet, in which Fritz and Bianca learn additional tactics and strategies. They learn about the Queen''s Gambit, blockades, additional checkmate patterns, passed pawns, the concepts of space and tempo, drawing strategies and variants including dice chess.' FROM games WHERE igdb_id = 356723 ON CONFLICT (game_id, language_code) DO NOTHING;
