INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jewel-quest-ii', 10473, '2009-08-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/slzs9kf1fcwbseapphdd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/cdkrq7zjah0b1okrwpnu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jewel Quest II', 'Trek through Africa in the return of the Ultimate Gem Matching Adventure. It’s 1944, and Rupert Pack returns. Join him as he hunts his way across the wild African safari, explores the lost Zimbabwe ruins, and surveys the majestic Victoria Falls on one of the worlds richest continents. Skilfully evade the menacing Sebastian Grenard while unearthing precious gems to ultimately escape with the grand jewel board. Get swept away by the heart pounding soundtrack as you''re immersed in realistic and authentic African settings. Discover an amazing new element of fun with the Exclusive "Duelling Jewels" Tournament Play: Pit your jewel matching skills against others around the world! Play against other players, or be matched with a computer opponent! Embark on a thrilling journey in a story filled with adventure, love, and betrayal that changes with every replay!' FROM games WHERE igdb_id = 10473 ON CONFLICT (game_id, language_code) DO NOTHING;
