INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('disney-fairies-tinker-bell-and-the-lost-treasure', 47790, '2009-11-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1krb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scs5if.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney Fairies: Tinker Bell and the Lost Treasure', 'Disney Fairies: Tinker Bell and the Lost Treasure expands on the forthcoming movie in which the Disney Fairies prepare for the Autumn Revelry, where Tinker Bell has been selected to create the prestigious Fall Scepter that can rejuvenate the Pixie Dust tree. When good friend Terence offers to help, Tinker Bell''s stubbornness and temper get the best of her, causing her to shatter her creation - the scepter''s fragile moonstone and her friendship with Terence. To make things right, Tinker Bell must now embark on a perilous quest to north of Never Land and find the Mirror of Incanta, which will grant her one wish.' FROM games WHERE igdb_id = 47790 ON CONFLICT (game_id, language_code) DO NOTHING;
