INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-legend-of-zelda-the-wheel-of-fate', 282978, '2009-08-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7n4i.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Zelda: The Wheel of Fate', 'The game follows the epic story of Din, last daughter of the dying Goddess Tribe. Her tribe alone knows the truth of Hyrule''s past, that Ganon, Zelda and Link are locked into an endless cycle of reincarnation, dooming Hyrule to continual recurring war. Din can break the cycle by finding and rejoining the three pieces of the broken triforce. Unfortunately, they are contained within the living bodies of Ganon, Zelda and Link, and the only way to get them out is to kill all three of them. Din must also find her two sisters, Nayru and Farore, who have gone out into Hyrule and never returned, for they hold the key to defeating the mysterious force that has kept the Goddesses from saving their world.' FROM games WHERE igdb_id = 282978 ON CONFLICT (game_id, language_code) DO NOTHING;
