INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('war-of-the-human-tanks-limited-operations', 11693, '2009-12-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3lv9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ark1p.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'War of the Human Tanks: Limited Operations', '"War of the Human Tanks - Limited Operations is the third game of the ''War of the Human Tanks'' series. In ''Japon'', a country bearing a close resemblance to modern-day Japan, ''Human Tanks'' have been fighting a sequence of wars against each other. Due to the reduction of ''radiotoxic particles'', their fuel, their era is considered to be about to end. While their end comes to one tank after another, the very final war of Human Tanks is on the verge of beginning. Seek out, charge and self-destruct to destroy your enemies in this strategy game! Lead your Human Tanks and complete your missions! This is a strategy game where you control Human Tanks - human-shaped tanks - and fight against other Human Tanks on the side of the hostile country. Scout out the enemy and plan your strategy, but remember that your tanks will go down in one hit and be lost forever. Key features: - Over 50 missions with strategic, semi real-time battles - Countless cute Human Tanks to battle with and against - Replay missions at any time to improve your rank - English localisation will feature hand-drawn battle backgrounds and an improved user interface"' FROM games WHERE igdb_id = 11693 ON CONFLICT (game_id, language_code) DO NOTHING;
