INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Charm Girls Club: My Perfect Prom', 'Charm Girls Club: My Perfect Prom takes girls through the thrills and drama of planning, fundraising, decorating, getting ready and attending the big night! Create endless trendy and stylish looks and customize a Charm Girl to reflect your unique style. Choose everything from hair, make-up, wardrobe, shoes and accessories! The Charm Girls, Anna, Sara, Olivia and Emilie, are the BFFs every girl dreams of. The Charm Girls will guide you on adventures, encouraging you along the way, like all best friends do. Choose the perfect dress, the perfect date and get ready for the big night in Charm Girls Club: My Perfect Prom.' FROM games WHERE igdb_id = 68086 ON CONFLICT (game_id, language_code) DO NOTHING;
