INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Texas Cheat ''Em', 'This is a casino-style card game in which players compete against others in a variation of Texas Hold ''Em poker. Players wager simulated money on hands they are dealt and can manipulate hands (i.e., cheat) while they are playing. Players can also engage in mini-games such as roulette, slots, and horse races to earn "cheat points" that allow specific advantages (e.g., seeing an opponent''s cards or changing their hand).' FROM games WHERE igdb_id = 92652 ON CONFLICT (game_id, language_code) DO NOTHING;
