INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Go Ballistic', 'Go Ballistic is a video redemption game requiring the players to physically move around by tossing soft play balls at an interactive touch screen. It includes five mini-games to choose from, each with distinct themes and missions. There is no restriction on the number of balls per game, so players can toss as many balls as they like within the time limit.' FROM games WHERE igdb_id = 152306 ON CONFLICT (game_id, language_code) DO NOTHING;
