INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chocolatier: Decadence by Design', 'Chocolatier: Decadence by Design is an economic sim focused on mouth-watering chocolate, and is the latest installment of the award-winning Chocolatier series. For the first time ever, you have complete control over the ingredients, look, name and description of your customized recipes. How you customize your chocolates has an economic impact on your success. Travel to ports around the globe to discover ingredients, build your empire, and follow the continuing saga of the Baumeister family.' FROM games WHERE igdb_id = 14999 ON CONFLICT (game_id, language_code) DO NOTHING;
