INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Infamous: Precinct Assault', 'Infamous: Precinct Assault is an Infamous series spin-off. The game was previously able to be found on the first Infamous game''s own website, as well a high score table. It is assumed that the game takes place during the events of Infamous, as Cole has powers and his iconic messenger jacket.' FROM games WHERE igdb_id = 374313 ON CONFLICT (game_id, language_code) DO NOTHING;
