INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bengarachou-hakubutsushi--1', 254611, '2009-07-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6o9g.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bengarachou Hakubutsushi', 'Tomohisa has some memory of his childhood. When he was a kid, he was often playing at some place near his house. But his parents don''t remember it. Tomohisa doesn''t remember it clearly, either. One day, he finds a notebook. It is about history and things happened at a small town. It''s just eccentric, so no one pays attention to it. But he knows who wrote it. It''s his uncle, who has been missing for years. The notebook includes a town he spent his childhood. He soon gets interested in the town and decides to visit there. Days later, he arrives at the town, but there are a lot of strange things and customs in the town. He finds various curious goods there and gradually gets to know a secret of the town and his past....' FROM games WHERE igdb_id = 254611 ON CONFLICT (game_id, language_code) DO NOTHING;
