INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Minions On Ice', 'Minions On Ice was a top-down player versus player MOBA made with Adobe Flash. It was a spinoff of Casual Collective''s previous game, Minions, with greater emphasis on unique minigames over team based combat. Players could pick from one of eight unique Minions to battle other players in Sumo, Race, and other modes.' FROM games WHERE igdb_id = 338125 ON CONFLICT (game_id, language_code) DO NOTHING;
