INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Championship Manager 2010 Special Edition', 'Championship Manager 2010 Special Edition is an updated version of the popular football management simulation game, Championship Manager 2010. It includes the full game along with additional content. The Special Edition features extras such as - Manager''s Notepad - Championship Manager pencil - Large Poster showcasing the structures of over thirty national leagues. - Additionally, it offers a subscription-based CM Live service that provides six updates during the football season, allowing players to manage their teams in real-time as the season progresses.' FROM games WHERE igdb_id = 324735 ON CONFLICT (game_id, language_code) DO NOTHING;
