INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DJ Max Fever', 'Based on DJMax Portable 2 but mixing elements from all the games, DJMax Fever features a brand new mix of music tracks, a re-balanced difficulty curve, new visual elements and more! The title packs in more than 100 songs for you to tap through, as well as a Freestyle Mode, Extreme challenges, five difficulty levels, Network Battle Mode and a collection gallery to house the music videos, soundtracks, and images you unlock.' FROM games WHERE igdb_id = 42892 ON CONFLICT (game_id, language_code) DO NOTHING;
