INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('3d-ultra-minigolf-adventures-deluxe', 29113, '2009-07-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r32.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/co2ipnqjxacj00csew5f.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3D Ultra Minigolf Adventures Deluxe', 'Whether you''re a seasoned player or just a beginner, get ready to tee off for a quick and fun match with four animated stylish characters. Putt your way through 36 fun-filled holes of minigolf on 3D designed courses with elevated greens, bunkers, bridges and water hazards, among other crazy obstacles. Also choose from an array of different environments to fit your mood that includes the Classic Carnival, Old West and Outer Space. Carefully Crafted 3D Courses  Sweeping, panoramic views of the holes and mind-bending course designs. 4-Player Multi-Player Mode  Choose from 4 highly detailed playable characters, each with their own personality and distinctive animations. 36 Challenging Holes  Based on three major themes: Classic Carnival, Old West and Outer Space. Creative Game Additions  Collect over-the-top power-ups and avoid imaginative traps to keep the game pace exciting and unpredictable. Customizable Course Editor  Build your own course design by mixing and matching combinations of tees, straights, corners, cups, junctions and ramps.' FROM games WHERE igdb_id = 29113 ON CONFLICT (game_id, language_code) DO NOTHING;
