INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pixelvader', 'Control a little ship in this space shooter style game. Start as a weak and harmless ship and power it up to beat all the death spitting war machines. The first level is easy, but you will need good reflex to beat the last level. Anyone who has had a seizure, loss of awareness, or other symptom linked to an epileptic condition should not play this game.' FROM games WHERE igdb_id = 335923 ON CONFLICT (game_id, language_code) DO NOTHING;
