INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mr. Driller: Drill Till You Drop', 'Mr. Driller: Drill Till You Drop offes non-stop Drilling Action! Featuring the classic addictive gameplay that the series is known for, this DSi game has over 40 stages of non-stop drilling action! Drill through a seemingly endless onslaught of colored blocks, avoid falling obstacles, and strategically manage your oxygen on the go with your Nintendo DSi!' FROM games WHERE igdb_id = 25176 ON CONFLICT (game_id, language_code) DO NOTHING;
