INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetris Giant', 'Tetris Giant, known as Tetris Dekaris in Japan, is a Tetris arcade game developed and published by Sega. The game can be played with up to two players on a large 70" DLP Projection Monitor, running on Sega System SP. It is controlled using giant joysticks, the right joystick being slightly lower than the left one, with a built-in shaker "rumble" motor, a device that Sega refers to as "Deka Lever" (deka is Japanese for large). The playing field is 6 cells wide by 7 cells high as opposed to almost universal 10 cells wide by 20 high.' FROM games WHERE igdb_id = 92457 ON CONFLICT (game_id, language_code) DO NOTHING;
