INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('88-constellations-for-wittgenstein', 352158, '2009-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa2cf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scxskh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '88 Constellations for Wittgenstein', '88 Constellations for Wittgenstein (to be played with the Left Hand) is an interactive, non-linear net.art piece that explores the life and philosophy of Ludwig Wittgenstein through a series of animated vignettes created in Flash. Each of the 88 sections corresponds to one of the 88 constellations in the night sky. Each constellation becomes a navigation device for the viewer to negotiate the associative relationships between these vignettes. As well, viewers can interact with each collaged animation using their left hand to trigger events from the computer keyboard. This work considers questions that Ludwig Wittgenstein pondered in his career as a philosopher: logic, language, the nature of thinking, and the limits of knowledge -- all in relation to our contemporary digital world.' FROM games WHERE igdb_id = 352158 ON CONFLICT (game_id, language_code) DO NOTHING;
