INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('drama-queens', 90949, '2009-05-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4aho.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scf2jf.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drama Queens', 'Take on the role of one of four girls as she tries to juggle boyfriends, careers, and best friends forever while encountering drama at every turn. Should she spend time at work trying to earn a promotion? Hang out with friends to build a closer friendship? Or go out on the town with that special guy in hopes of finding the love of her life? It’s all up to you. With all of life’s twists and turns, you never know what’s going to happen next in Drama Queens! Compete with up to 3 friends to see who’s more popular in Multi-Card Play or “Hot Seat” where you take turns on one DS. Spin the wheel and choose your path to move your character around the 3D board game environment! Beware of the Drama Spaces as they can lead you to lose your job, have a Best Friend Forever stand you up, or cause another girl to steal your boyfriend!' FROM games WHERE igdb_id = 90949 ON CONFLICT (game_id, language_code) DO NOTHING;
