INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CID: The Dummy', 'Save the world, the day, and the girl in CID The Dummy, an action-adventure game. The game comes with high speed crashes, turbo-charged weapons, kung-fu fighting, mind-boggling puzzles and level systems and more monsters than you can shake a super-charged fire-blazing bazooka at. Join CID to save the world, the day and the girl in this year''s most daring adventure.' FROM games WHERE igdb_id = 4765 ON CONFLICT (game_id, language_code) DO NOTHING;
