INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Party: Fushigi no Koro-koro Catcher', 'Mario Party: Fushigi no Koro-koro Catcher is an arcade medal game based on Mario Party 8. Up to 16 players can play at once. It includes some boards and minigames from the aforementioned Nintendo Wii title, although some are modified. Gameplay also revolves around a rotating carousel in the middle containing balls, which the player must try to grab with a crane at certain points in the game.' FROM games WHERE igdb_id = 77829 ON CONFLICT (game_id, language_code) DO NOTHING;
