INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pokewalker', 245421, '2009-09-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6yas.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scnz9h.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokéwalker', 'The Pokéwalker is a pedometer device specifically for use with Pokémon HeartGold and SoulSilver that is able to interact with the games in various manners. It was released in Japan on September 12, 2009 bundled with every copy of Pokémon HeartGold and SoulSilver, and then later released with every localized copy of the games. The accessory has a Poké Ball design with a small monochrome LCD screen and three functioning buttons. The Pokéwalker supports infrared signals allowing players to interact within a short range with a game card of Pokémon HeartGold or SoulSilver while slotted in the Nintendo DS, or with another Pokéwalker. The system records every time a step is taken, and the daily step count influences which wild Pokémon and items will appear. The player can transfer a Pokémon to the Pokéwalker from either HeartGold or SoulSilver, which gains experience for each step. Like the Pokémon Pikachu and Pokémon Pikachu 2 GS, the Pokéwalker uses a currency known as "Watts" (shortened to w); every 20 steps will earn the player one watt. Players can also catch various Pokémon and obtain items on the device, then transfer them to the game. Alongside the Johto Safari Zone, the Pokéwalker allows for Pokémon normally unavailable until after the player has traveled to Kanto, such as Murkrow, to be available before defeating the Johto League. Much as HeartGold and SoulSilver are remakes of the original Gold and Silver, the Pokéwalker could be considered to be somewhat of a remake of Pokémon Pikachu 2 GS, which interacted in much the same way with the Generation II games. Unlike Pokémon Pikachu 2 GS, however, Pikachu is not the only Pokémon that can be interacted with, and Pokémon can actually be transferred to and from the Pokéwalker at any given time.' FROM games WHERE igdb_id = 245421 ON CONFLICT (game_id, language_code) DO NOTHING;
