INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Price is Right: 2010 Edition', 'The Price is Right features all of your favorite pricing games, from Plinko, to Cliff Hangers, to Golden Road, and more. Experience all of the classic moments from the show with up to four players - you''ll hear your name called as you''re announced to "Come on Down" to Contestant''s Row. Compete from Contestant''s Row, through classic pricing games, the wheel, and, finally, get your chance to win the big prizes in the Showcase Showdown.' FROM games WHERE igdb_id = 50650 ON CONFLICT (game_id, language_code) DO NOTHING;
