INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Trench Run', 'Star Wars: Trench Run is a rail-shooter set during Star Wars Episode IV. The game depicts the final space battle of the Rescue of Princess Leia and the Battle of Yavin, particularly the fateful trench run Luke Skywalker took to destroy the Death Star.' FROM games WHERE igdb_id = 21743 ON CONFLICT (game_id, language_code) DO NOTHING;
