INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BombLink', 'BombLink is a fast-paced puzzle game where you connect bomb fuses to set off massive chain reactions. Falling flames ignite the linked bombs, rewarding bigger scores for longer chains. With multiple bomb types, three game modes (Endless, 30 Attack, 100 Attack), adjustable difficulty, and support for custom music, it blends explosive action with strategic fuse-linking fun.' FROM games WHERE igdb_id = 364320 ON CONFLICT (game_id, language_code) DO NOTHING;
