INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blosics', 'Blosics is a Flash-based puzzle-physics game where the player must shoot balls at green blocks to knock them off the screen. Doing this will award points and the player must meet a certain point threshold to move onto the next level. It cost points to shoot a ball, and the larger the ball, the more points it''ll use up. The player must also refrain from knocking red blocks off the screen, as they subtract points from the score.' FROM games WHERE igdb_id = 261920 ON CONFLICT (game_id, language_code) DO NOTHING;
