INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Giraffe Above', 'Mmmmm apples. You’re an apple-crazy Giraffe on a mission to gobble all the apples in Africa! Your objective is to collect the apples in the tree in one continuous line and then get your head to the exit. The tricky part is not crossing your neck at any point or blocking your head into a corner! You only have a limited amount of time to do this and the puzzles become more difficult as you progress through the game.' FROM games WHERE igdb_id = 340154 ON CONFLICT (game_id, language_code) DO NOTHING;
