INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meet''N''Fuck: BDSM Club', 'Recently I met a very sexy girl. Her name was Rachel. She was telling a lot of stories from her weird sexual life. At the first time, I didn''t believe her of course. But on my birthday, she gave me a flyer to BDSM club of Madam Vinson.' FROM games WHERE igdb_id = 221726 ON CONFLICT (game_id, language_code) DO NOTHING;
