INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SingStar: Chartbreaker', 'SingStar Chartbreaker is a game of the SingStar Series released in Germany. Tracklist 1. Adamski Killer 2. Ann Lee 2 Times 3. Baltimora Tarzan Boy 4. Black Wonderful Life 5. Charles and Eddie Would I Lie To You 6. China Crisis Wishful Thinking 7. Cinema Bizarre Lovesongs (They Kill Me) 8. Daryl Braithwaite One Summer 9. David Dundas Jeans On 10. Eighth Wonder I''m Not Scared 11. Emilia Big, Big World 12. Harpo Moviestar 13. Joshua Kadison Jessie 14. Lisa Stansfield All Around The World 15. Marc Almond feat. Gene Pitney Something''s Gotten Hold Of My Heart 16. Marshall Hain Dancing In The City 17. Max Werner Rain In May 18. Maxi Priest Close To You 19. OMC How Bizarre 20. Orange Blue She''s Got That Light 21. P. M. Sampson We Love To Love 22. Ashford & Simpson Solid 23. Samantha Fox Touch Me (I Want Your Body) 24. Sniff''n The Tears Driver''s Seat 25. Talk Talk Such A Shame 26. Tasmin Archer Sleeping Satellite 27. Thomas Godoj Love Is You 28. Thompson Twins Doctor! Doctor! 29. Watershed Indigo Girl 30. Whigfield Saturday Night' FROM games WHERE igdb_id = 136395 ON CONFLICT (game_id, language_code) DO NOTHING;
