INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('egypt-solitaire', 343628, '2009-06-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9t12.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scwsxo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Egypt Solitaire', 'Welcome to Egypt Solitaire, the classic solitaire game with a twist of Ancient Egyptian flair! This game will take you on a journey through a captivating world of hieroglyphs and temples, while you play a classic game of solitaire. Egypt Solitaire features incredibly realistic graphics and sound effects to give you the most immersive experience possible. The aim of the game is to move all of the cards from the tableau to the foundations. In the tableau, the cards are arranged in seven piles and the top cards of each pile are turned face up. The foundations are located at the top of the playing area and are made up of four piles with increasing amounts of cards. You can move cards from the tableau to the foundations by either building up or down in sequence. You can also build in-suit sequences by moving the top card of a pile to the top of another pile, if it is of the same suit. If a player is unable to make any more moves, they can draw three new cards from the stock pile. However, once the stock pile is exhausted, the game is over and the player has lost. Egypt Solitaire also comes with multiple difficulty levels, ranging from easy to expert, which makes it suitable for players. Enjoy!' FROM games WHERE igdb_id = 343628 ON CONFLICT (game_id, language_code) DO NOTHING;
