INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hunting-challenge', 145561, '2009-09-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2xgd.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hunting Challenge', 'Hunting Challenge and its new accessory (a hinged barrel hunting gun using the nunchuck and the wiimote) take up the challenge of making you live or relive the experience of real hunting in plains or swamps, with an immersion and reality quality never before achieved. With your weapon in your hand, binoculars hung around your neck, decoy in your pocket, and a hunting dog obeying your every order, move around in beautiful surroundings and get to know each species (whether they can be hunted or not) along with their favorite territories, habits and behaviors. Proximity, noise, weather conditions and wind direction are all settings that should be taken into account when planning to go hunting, while complying with all the hunting laws currently in effect. Main Features: * A new accessory imitating a real hunting gun (the barrel must be broken open in order to reload it!) * The first real hunting simulation on a new generation console * 2 kinds of hunting: Aquatic game hut hunting and hunting in plains. * Ball-Trap mode in bonus! * Set up your hunt according to your preferences: Hunting zones, weather conditions (mist, fog, rain), time of day. * Be attentive to the wind direction so that you don''t alert the game. * Direct your hunting dog like you would do in reality! * 18 different hunting areas to choose from. * 11 species with explanations and advice for each of them: Mallard, coypu, deer, boar, stag, fox, goose, partridge, snipe, pheasant, rabbit… * A significant amount of information on current hunting laws.' FROM games WHERE igdb_id = 145561 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 145561 AND p.igdb_id = 5 ON CONFLICT DO NOTHING;
INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 145561 AND rs.code = 'PEGI' AND r.code = '12' ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('topatoi-spinning-through-the-worlds', 52981, '2009-07-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7kpl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9i4b.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Topatoi: Spinning Through the Worlds', 'Raph, a brave explorer, and his companions have crash-landed in a mysterious corner of a strange planet. Now Raph must hunt for the spare parts needed to fix their skyship - and save his girlfriend too. Fortunately, our hero has access to the amazing GEMMA - the ''Gyroscopic Exploration Multidimensional Multiterrain Apparatus''. It''s a small explorer vehicle that works like a spinning top - which is perfect for the crazy part of the world our characters are trapped in. Controlling GEMMA needs some practice. It''s spin needs to be controlled carefully, as the degree of spin - and therefore its overall speed - directly affects its movement and behaviour. GEMMA can also be upgraded with special abilities to help you on your journey, too. Sounds like a solid platform/puzzler, don''t you think?' FROM games WHERE igdb_id = 52981 ON CONFLICT (game_id, language_code) DO NOTHING;
