INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hot Wheels: Battle Force 5', 'Battle Force 5 is an elite team of teens whose mission is simple – to defend against the robotic armies of The Sark and the brutal and barbaric Vandals who are intent on invading Earth. Armed with 5 super-cool, ultra-fast, and battle-ready vehicles, team Battle Force 5 must race, smash, and bash these aliens in an effort to protect the fate of the Earth. Your mission is simple – defend the Earth from invading aliens with your battle-ready vehicle. Race, smash, and bash your way to victory. The fate of our planet hangs in the balance.' FROM games WHERE igdb_id = 4915 ON CONFLICT (game_id, language_code) DO NOTHING;
