INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Infamous: Special Edition', 'Infamous tells the story of delivery boy Cole McGrath & the day he delivers a mysterious object called the Ray-sphere which explodes causing him to inherit mysterious electrical super powers. As his city begins to fall to bandits, it is up to Cole using his new found powers to save the city or to take it for himself. This Special Edition contains: - Fold-Out Comic Book Style case - Game Disc - Art Book - Gigawatt Blades Weapon DLC' FROM games WHERE igdb_id = 44669 ON CONFLICT (game_id, language_code) DO NOTHING;
