INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nirin', 'Hop on your choice of five bikes and race through crowded city streets in Bandai Namco’s Nirin! Five courses offer tons of compelling scenery and a range of difficulties. The gameplay is easy for first time users, but there is a definite advantage to the experienced rider who has mastered the boost feature. Bank hard through turns to build the boost meter, and then straighten the bike out to blast past your rivals! For even more speed, draft behind cars, trucks, and other motorcycles.' FROM games WHERE igdb_id = 380177 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 380177 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
