INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Birthday Party Bash', 'Birthday parties will never be the same with Birthday Party Bash! Up to 12 partygoers can whack, roll, splash, pop, and shimmy their way through over 20 birthday games, including twists on classic favorites like Piñata Blast, Duncan Hines Cake Stacker, and Birthday Blowout. Ten party theme rooms set the scene for an unforgettable bash, from “Pirates” to “Princess”. When it’s cake time, everyone can sing along to “Happy Birthday.” Free party invitations included in the box! The game comes with 12 Birthday Party Invitations in the box, a great "buy one get one free" coupon or the party sweets and the manual doubles as a party planning tool with party tips, recipes and more! Up to 12 players can play via 4 player turn-based play.' FROM games WHERE igdb_id = 4718 ON CONFLICT (game_id, language_code) DO NOTHING;
