INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'HentaiVerse', 'The HentaiVerse is a free browser-based online RPG launched in 2009 by E-Hentai.org and found at hentaiverse.org. In the HentaiVerse players fight monsters in a variety of battle modes in order to gain EXP and level up as well as earn credits and various items. The game lacks graphic erotic content, except for the funny names of the monsters being fought.' FROM games WHERE igdb_id = 356129 ON CONFLICT (game_id, language_code) DO NOTHING;
