INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wedding Dash 2: Rings Around the World', 'Quinn is back on a new whirlwind adventure, joined by Flo and Joe Wright, wedding photographer. Help Quinn become the world''s top wedding planner in this hilarious sequel to the hit game Wedding Dash. Visit beautiful, exotic locations while managing new guests, fulfilling bride and groom requests, and tackling comedic disasters. Do you have what it takes to help Quinn win the honor of planning the most exclusive wedding of the year?' FROM games WHERE igdb_id = 16074 ON CONFLICT (game_id, language_code) DO NOTHING;
