INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toradora Portable!', 'Toradora Portable! is developed by Guyzware and published by Namco Bandai Games. The player assumes the role of Ryuuji Takasu where he moves around school and town, conversing with characters and working towards multiple endings as part of an original storyline. The game also features a minigame where players play as Taiga, fending off lovesick guys.' FROM games WHERE igdb_id = 42752 ON CONFLICT (game_id, language_code) DO NOTHING;
