INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('paws-and-claws-pampered-pets', 29197, '2009-07-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob8ua.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/zk4cs3tcppinecebhqms.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paws & Claws: Pampered Pets', 'Only the best for your pets! Luxury and extravagance are the way of life at the Pampered Pets Spa. Let the pampering begin!Features Time for TLC! Welcome your clients to your Pampered Pets Spa to style and spoil your pets. Bling! Create custom diamond collars, sequined bags and more in your very own Pet Shop. Posh pad! Welcome your VIPets to their very own luxurious themed room including the Pretty in Purple and You’re a Movie Star rooms. Secret to Success! Grow your Pet Spa business as you receive gold star recommendations from your satisfied customers. Spare No Expense! Expand your custom treatments such as water aerobics and acupuncture in the Wellness Center. Pamper your VIPets with nothing but the best treatments including massage therapy and oxygen tents. Become the star of the business welcoming your guests with a limo ride from the airport. Offer your Pet Spa customers posh accessories and lavish personal pet rooms.' FROM games WHERE igdb_id = 29197 ON CONFLICT (game_id, language_code) DO NOTHING;
