INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Modern War: Somalian Pirates', 'The player escorts a variety of civilian ships by either helicopter or by boat. The one and only objective is to use a Gatling gun to destroy small boats filled with Somali pirates armed with automatic rifles and RPG launchers.' FROM games WHERE igdb_id = 64321 ON CONFLICT (game_id, language_code) DO NOTHING;
