INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ringling Brothers and Barnum & Bailey', 'If you''re ready to soar through the air as a human cannonball, perform with magnificent Bengal tigers, defy gravity on a motorcycle in the Spherical Miracle, dazzle the crowd with aerial acrobatics, clown around in a juggling jamboree and dance with an exotic Asian elephant… then you''re ready for the fun and thrill that can only be experienced at Ringling Bros. and Barnum & Bailey.' FROM games WHERE igdb_id = 51136 ON CONFLICT (game_id, language_code) DO NOTHING;
