INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Run!', 'Simple to understand, yet challenging to master, Run! is an addictive game where you must jump, slide, defend and destroy your way through an eccentric variety of obstacles while running at increasingly faster speeds. You''ll have to punch/kick obstacles out of your way, and launch missiles at others to destroy them before they destroy you. The controls are simple: swipe up to jump, swipe down to slide, tap the attack button to punch/kick, and tap on certain obstacles to fire missiles and destroy them.' FROM games WHERE igdb_id = 100256 ON CONFLICT (game_id, language_code) DO NOTHING;
