INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ni Hao Kai-lan: Super Game Day', 'Based on the hit Nickelodeon show for preschoolers Allows children to play as favorite characters from the show as Kai-lan and her friends savor a fun and happy day together Features 10 fun-filled mini games, including butterfly catching, kite flying, dragon boat racing, bubble popping, badminton and soccer challenge Multiplayer option lets kids engage in friendly competition with a pal Designed to encourage good sportsmanship and broaden kids'' cultural awareness' FROM games WHERE igdb_id = 50715 ON CONFLICT (game_id, language_code) DO NOTHING;
