INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hula Wii: Tanoshiku Hula wo Odorou!!', 'This fitness game has players using the Wii remote controller to hula dance to various songs. Videos of professional hula dancers provide guidance to help players learn. In addition to standard hula dancing, it also features Tahitian dance. A two-player mode lets two players dance together to the same song. Unlike the first game, this entry only supports the Wii remote and doesn''t support the balance board.' FROM games WHERE igdb_id = 268171 ON CONFLICT (game_id, language_code) DO NOTHING;
