INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rosemary', 'When Rosemary discovers a photograph of a forgotten friend, she is driven back to her old haunts to piece back together her memories and unravel what happened to him. She finds herself questioning her memories of the people and places she interacted with in her childhood. Rosemary is a point-and-click adventure game with a twist: the player has to explore and arrange the memories of the character in order to solve the mystery of the game.' FROM games WHERE igdb_id = 91829 ON CONFLICT (game_id, language_code) DO NOTHING;
