INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chou Meisaku Suiri Adventure DS: Raymond Chandler Gensaku - Saraba Itoshiki Hito yo', 'This DS game is a visual novel game adaptation of "Farewell, My Lovely" detective novel written by Raymond Chandler which spanned several movie adaptations. This time, the player takes on the role of Philip Marlowe, private investigator. While on a case, a big guy called Moose Malloy enter the bar looking for his old flame, Velma Valento. Marlowe steps in to calm down the big guy and hears his story. Seems he''s been in prison for 8 years and Velma wasn''t interested in waiting. Marlowe reluctantly offers his help if Moose promises to calm down and not do anything rash in the meantime. Expecting a quick conclusion, the great P.I. finds himself entangled in Velma''s drama filled with intrigues and deceptions.' FROM games WHERE igdb_id = 269583 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 269583 AND p.igdb_id = 20 ON CONFLICT DO NOTHING;
