INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Thrill of Combat', 'The Thrill of Combat is quite possibly one of the most disorientating experiences you’ll ever have, even though the concept sounds simple (if a little bizarre): fly your helicopter into enemy territory, kill the soldiers, cut out their vital organs—and repeat.' FROM games WHERE igdb_id = 242925 ON CONFLICT (game_id, language_code) DO NOTHING;
