INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Backyard Baseball ''10', 'Combining all the elements of a realistic sports title with the thrilling action of a crazy arcade game, Backyard Baseball ''10, is the ultimate kids'' baseball experience with new fields, detailed graphics, precise game controls, and a beefed up MLB roster including David Big Papi" Ortiz, who is returning for a second season as the game''s cover player. Along with Ortiz, Backyard Baseball ''10, let''s kids play with or alongside other pro players featured as kids in full uniforms including stars from all 30 MLB teams such as Ken Griffey Jr., Ichiro, Vladimir Guerrero, Albert Pujols, Alfonso Soriano, and Ryan Howard. As kids play more, they are able to unlock several additional stars.' FROM games WHERE igdb_id = 6572 ON CONFLICT (game_id, language_code) DO NOTHING;
