INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nezumi Man', 'Nezumi Man is a homage to/parody of the classic NES Mega Man games, starring a rat who can run, slide, jump and shoot like the Blue Bomber himself. His goal is to stop the plans of Dr. Gyoniku and his henchmen, along with seven other rat and ratlike characters. The game was an entrant in the 2009 HSP Program Contest. It is notable for its humorous characters and situations.' FROM games WHERE igdb_id = 276480 ON CONFLICT (game_id, language_code) DO NOTHING;
