INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Mini Golf 2', 'It''s time to get into the mini swing of things with Crazy Mini Golf 2! Choose from 4 differently themed worlds and 18 fun and challenging holes in each world. With the ability to customize your golf avatar from your head to your shoes with thousands of possibilities, great multiplayer mode and Wii MotionPlus support, this might possibly be the most fun you''ve ever had on a miniature golf course!' FROM games WHERE igdb_id = 50640 ON CONFLICT (game_id, language_code) DO NOTHING;
