INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animal Life: Dinosaurs', 'Explore the dinosaur continent Pangea In ,,Animal Life - Dinosaurs" you start a fantastic voyage into the past. You''ll get into the world of dinosaurs, solve tricky quests and experience exciting games. The more you know about dinosaurs, the more the puzzles and dinosaurs you''ll get to see. Collect all stars to become a real pro in the field of dinosaur research!' FROM games WHERE igdb_id = 269552 ON CONFLICT (game_id, language_code) DO NOTHING;
