INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Number Munchers', 'Munch on Math! Help your Muncher avoid the mischievous Troggles as you maneuver through the gameboard, munching on multiples, factors, prime numbers, equalities and inequalities. If you earn enough points and avoid those troublesome Troggles, you''ll be sure to enter the Muncher Hall of Fame!' FROM games WHERE igdb_id = 50339 ON CONFLICT (game_id, language_code) DO NOTHING;
