INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('barbie-and-the-three-musketeers', 45176, '2009-10-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2dbt.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barbie and the Three Musketeers', 'It’s “All for one and one for all” as Barbie and her friends star together in Barbie and the Three Musketeers, a classic story with a girl power twist! Join Barbie on the adventure of a lifetime! Play as Corinne, a girl from the French countryside who dreams of becoming a musketeer. Joined by three other musketeer hopefuls, together the girls will use their unique abilities to tackle obstacles and puzzles across a dozen locations from the movie. Ultimately, through the power of friendship and teamwork the girls uncover a plot against the prince and save the day, achieving their dreams and becoming true musketeers! Play as Barbie''s character Corinne or one of her Three Musketeers friends - Viveca, Renee, or Aramina Each character possesses different and unique abilities that help you complete missions ? specialties that include grapples, ribbon whips, Chinese fans, leaping and dancing Explore the environment ? from the French countryside to Paris Solve challenging puzzles and discover treasures on your journey to save the Prince' FROM games WHERE igdb_id = 45176 ON CONFLICT (game_id, language_code) DO NOTHING;
