INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Iron Master: The Legendary Blacksmith', 'When a war is going on, blacksmiths are critical. In Iron Master: The Legendary Blacksmith, players take on the role of one of these blacksmiths. The main focus of the game is forging. Forging equipment is done through a mini-game in a step-by-step process. Casting, chopping, cutting, tempering, stretching, hammering, and melting are involved in this complex process.' FROM games WHERE igdb_id = 67991 ON CONFLICT (game_id, language_code) DO NOTHING;
