INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tap Jockey', 'Tap Jockey is a horse racing game. You run your horse by tapping the screen and adjusting its speed. Each horse has values on 3 features; "speed" "stamina" and "sense". You can create a unique horse by adjusting each value with points earned at races. Points are awarded when you win a race, then you can adjust each features before proceeding to the next race (maximum 6 races).' FROM games WHERE igdb_id = 175260 ON CONFLICT (game_id, language_code) DO NOTHING;
