INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Generation Xth: Code Realize', 'Code Realize is the final game in the "Generation Xth" trilogy.  It is a first person dungeon crawling RPG with turn based combat released for PC in Japan. You use a team of 6 people to explore the Abyss. The game allows you to carry over your save file from the previous game.' FROM games WHERE igdb_id = 14684 ON CONFLICT (game_id, language_code) DO NOTHING;
