INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('besser-essen-leben-leicht-gemacht', 269715, '2009-03-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7660.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Besser Essen: Leben Leicht Gemacht', 'The game to the successful TV format now makes it possible for anyone to deal individually with their own diet while traveling or at home. With the unique nutritionist for Nintendo DS, losing weight is a breeze and fun! Healthy life is in vogue! Better Food Life Made Easy is based on the Pro7 documentary series, written by renowned physician and bestselling author Dr. Stefan Frädrich is moderated. Finally, there is his valuable advice on life coaching, delicious recipes and nutritional advice for the DS! Better food life made easy accompanied with personalized meal plan suggestions and effective healthy eating tips through the day. In 35 lessons, you acquire playfully essential knowledge for better nutrition. Your personal dietary goals are always kept in view with the daily planner. With a daily planner for diets, top 10 lists of tips and aids, food-themed minigames and more than 100 recipes from starters to desserts, Besser Essen offers everything that makes life easier.' FROM games WHERE igdb_id = 269715 ON CONFLICT (game_id, language_code) DO NOTHING;
