INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vampire Saga: Pandoras Box', 'With a chilling crime at the center of its spellbinding story, Vampire Saga is not intended for the faint of heart. Join Matthew Ward as he steals aboard a cargo ship to escape the violence of the Spanish-American War, passes out and then wakes up to find himself alone with several sinister-looking coffins. Explore eerie locations, search for hidden objects and follow a story full of nerve-pricking encounters. Without a doubt, this captivating mystery thriller will give you the creeps!' FROM games WHERE igdb_id = 53935 ON CONFLICT (game_id, language_code) DO NOTHING;
