INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Murder, She Wrote', 'Murder, She Wrote is a hidden object game based on the TV series starring Angela Lansbury. There are five cases to be solved, presented as books on a shelf. Each case can be played with or without a time limit, displayed as a clock at the top-left corner of the screen. The plot is developed through cartoon cutscenes with full voice acting, that appear at the beginning of each case and in certain pivotal moments.' FROM games WHERE igdb_id = 67185 ON CONFLICT (game_id, language_code) DO NOTHING;
