INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Penguin Catapult 2', 'Crazy Penguin Catapult 2 is the sequel to the 2008 iOS game Crazy Penguin Catapult. Gameplay is comprised of multiple missions, each broken up into two parts. The first half involves using a catapult to fling penguins through a gap in the wall. Those penguins that make it through are then brought into the second half, in which the player drops the penguins into an area filled with polar bears. If enough polar bears are hit by the penguins, the missions is completed.' FROM games WHERE igdb_id = 67968 ON CONFLICT (game_id, language_code) DO NOTHING;
