INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Back Door Man', 'Miami is a rough town: Crime, drugs, humidity... but for an enterprising male prostitute, all that matters is satisfying the clients and getting paid. The life isn''t as glamorous as it seems, though, as you''ll soon find out by guiding our man through one crazy night. This game was originally created for The Independent Gaming Source''s Adult/Educational Competition, which won 2nd place. Please note that this game is intended for mature audiences (17 years or older).' FROM games WHERE igdb_id = 57997 ON CONFLICT (game_id, language_code) DO NOTHING;
