INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oi Katamari Damacy-Kun', 'Oi Katamari Damacy-Kun (オーイ塊魂くんlit, Oi Katamari Damashii-Kun) is the sequel to Katamari Damacy-Kun. This game had new additions, such as a non-autoscroll stage, the ability to play as different cousins, and the story appears to be based around gacha toys. The total number of playable levels in the sequel is 24.' FROM games WHERE igdb_id = 243429 ON CONFLICT (game_id, language_code) DO NOTHING;
