INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SingStar: Mecano', 'SingStar: Mecano is a karaoke game which exclusively features songs by the Spanish group Mecano. There are no changes to the gameplay formula: player(s) sing into a microphone and the game gives points based on the performance. The only basis of assessment is if the correct note is hit with the correct timeing; the sung words or octave does not play into the result.' FROM games WHERE igdb_id = 44701 ON CONFLICT (game_id, language_code) DO NOTHING;
