INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WordJong Party', 'A Whole New Way to Spell Party! The smash online and DS puzzler WordJong is coming to Wii with all-new multiplayer modes, gorgeous new visuals and more! Use a set of lettered tiles to create words and clear the board in both single-player & intense 4-player modes. WordJong Party boasts several new features exclusive to the Wii including four-player Party Mode, new power-ups, an enhanced Solo Mode, and more!' FROM games WHERE igdb_id = 51025 ON CONFLICT (game_id, language_code) DO NOTHING;
