INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snow Moto Racing', 'Dohi Entertainment are proud to present Snow Moto Racing, the first snowmobile racing game on the iPhone/iPod Touch platform. Experience the thrill of high-speed snowmobile racing while carving your path through beautiful winter landscapes. Perform stunts to trigger speed boosts that will give you the edge when racing against your opponents.' FROM games WHERE igdb_id = 63837 ON CONFLICT (game_id, language_code) DO NOTHING;
