INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mahjong!!', 'Mahjong Solitaire is a matching game for one player. The goal of the game is to remove all tiles out of the board by pairs. Select tiles with the same picture and they will disappear. Only free tiles that are not covered are allowed to remove. MahJong features: - 20 background pictures - 9 tilesets - hint, undo and shuffle board options - shadow option - clear big tiles - autosave when exit or take a call - no interference with music player' FROM games WHERE igdb_id = 89107 ON CONFLICT (game_id, language_code) DO NOTHING;
