INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('love-is-dot-dot-dot-in-bloom', 51160, '2009-11-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/wtlg2axoq5fpipn8qyd6.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Love is... in Bloom', 'Love Is... playing together. Now heres your chance with Love Is... In Bloom on the Nintendo Wii. Plant, nurture and sell flowers to build your own floral empire and a great relationship at the same time!  Take on the role of the popular Love Is... characters in their goal to build the best Florist shop around. Start with the basics of preparing the soil and planting seeds to grow magnificent flowers that you can then sell them in your very own Flower shop to earn money and grow a little empire.  Full of the same endearing charm as the original cartoons you get to work on a blossoming relationship as well as a growing business.  * Twelve varied and unique arcade-style games provide fun, long-term challenges.  * Build your own floral empire. Starting from the very first seed and building up, upgrading the garden and stocking the shop to supply made-to-order bouquets to the public.  * Unique Wii-remote controls with gameplay specifically designed to take advantage of the extra level of control.  * Single and Multiplayer game modes.' FROM games WHERE igdb_id = 51160 ON CONFLICT (game_id, language_code) DO NOTHING;
