INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Imagine: Music Fest', 'You’ve just scored a chance to attend the premier Music Fest, where you’ll be in charge of creating a band, designing their look, and putting on a rockin’ concert! Design your band''s logo, customize the look of their instruments, hair, and wardrobe, and earn cash to buy cool new clothes and accessories for your band!' FROM games WHERE igdb_id = 7932 ON CONFLICT (game_id, language_code) DO NOTHING;
