INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('freeze-tag-fun-pack-number-1', 16100, '2009-08-03', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/sco3f0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Freeze Tag Fun Pack #1', 'Traverse a map of an ancient land and solve plenty of puzzles on the way.  Control the chameleon idol and, using its magic power, blast gems before they reach the hole. At the end of each level, the score is converted to money that you can spend at the shop to buy extra lives or new skins for the chameleon. Each skin comes with different powerups and effects. Catch a boatload of fishy fun in this original arcade challenge! Load up the RV and crisscross the country in a series of tournaments that will put your angling prowess to the test. Cast your line in colorful locations like Bullhorn Lake, Golden Corn Lake, and Wicked Mansion Lake. Catch fish to earn points and climb to the top of the rankings in the amateur, pro, and elite circuits. Your fellow fishers are sure to keep you on your toes, but watch out for surprises swimming just below the surface that will slow you down. Featuring innovative gameplay, colorful full-screen graphics, and hours of fun for the whole family, Fishing Craze is no fish-tale, it''s the real thing! Catch it today.' FROM games WHERE igdb_id = 16100 ON CONFLICT (game_id, language_code) DO NOTHING;
