INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Big Mountain Snowboarding', 'Realistic 3d snowboarding for android. Ride 16 huge trails each featuring a real mountain feel. Race to the bottom, slalom between the gates, or rack up big points with spins and grabs.  Each trail is a different challenge with multiple ways down the mountain. Features trick parks, race courses, and big mountain cliffs. Tilt to turn, lift to jump, and touch the screen to grab your board or to tuck.' FROM games WHERE igdb_id = 88322 ON CONFLICT (game_id, language_code) DO NOTHING;
