INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monkey Flight', 'Launching JABBERING MONKEYS from a palm tree has never been this fun... and harmless! Use your catapulting skills to become the KING OF THE JUNGLE, but watch out for dirty mud pools and ouchy rocks, or you might end up as the troop''s back scratcher or tree shaker. This is JUNGLE CATAPULTING at its best!' FROM games WHERE igdb_id = 106452 ON CONFLICT (game_id, language_code) DO NOTHING;
