INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Guard', 'Star Guard is a 2D platformer brought back to the basic elements of the genre: jumping and shooting, with a distinct retro look. Enemies are red, allies are green and the levels consist of yellow lines against a black background. The player controls a spaceman on a mission to defeat an evil wizard, armed only with a single gun that fires in the direction the character is facing.' FROM games WHERE igdb_id = 185136 ON CONFLICT (game_id, language_code) DO NOTHING;
