INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('active-health-with-carol-vorderman', 67620, '2009-08-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa1v8.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Active Health with Carol Vorderman', 'Active Health with Carol Vorderman comes packed with a sleek, specially designed pedometer, called an Activity Meter, which monitors your activity levels throughout the day when placed in your bag or pocket. Carol provides you with a daily step target and at the end of each day you simply point the Activity Meter at the Nintendo DS, like a TV remote control, and with one click of the button your data will be sent to your DS by infrared signal. Additional activity can also be entered into the software so whether you go for a long walk, a swim or do some gardening, it will all count towards your daily activity goal. You can input your Wii Fit activity into Active Health to keep track of additional exercises completed on the Wii. On the path to reaching your goal, you can earn incentive points by maintaining exercise levels and selecting healthy food options as part of your diet programme. As points are earned, additional features such as new background music and images become unlocked. Active Health with Carol Vorderman also offers a variety of fun mini-games to help motivate you to keep healthy such as the Walking Challenge which converts your steps into miles so you can attempt to walk the distance between Land’s End and John O’Groats! To help improve your knowledge of the calorie count of popular foods Calorie Count Up is a mini game you can play alone or against Carol. You have to choose items from a selection shown on screen and see if you can reach the target of 1,000 calories. Active Health with Carol Vorderman is a simple and motivating way to get you on track to a healthier lifestyle. It’s easy to use, fits around your life and can help to bring the fun back into healthy living. Active Health with Carol Vorderman helps you work towards a balanced lifestyle by focusing on your exercise regime, diet and fitness goals with: Regular Exercise - Pop the Activity Meter in your pocket, then beam walking data to your DS. All exercises, like swimming or playing on Wii Fit can be added, too. Healthy Eating - Input your meals for nutritional information. Unlock new recipes, then add the ingredients to a shopping list. Fitness Goals - Set step goals and calorie targets, then see if you can stick to them and reach your ideal fitness levels.' FROM games WHERE igdb_id = 67620 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 67620 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 67620 AND p.igdb_id = 20 ON CONFLICT DO NOTHING;
INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 67620 AND rs.code = 'PEGI' AND r.code = '3' ON CONFLICT DO NOTHING;
