INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paws & Claws Pet Vet: Australian Adventures', 'Get ready for an adventure at your very own Paws & Claws Pet Vet clinic down under! It’s your job to nurture and love all of the wild animals down under and bring them back to health. Work as a doctor and care for 6 fun loving animals such as koala bears, wombats, dingoes and kangaroos! Be an entrepreneur! Use the profits from your Pet Vet clinic to expand your business and increase your clinic’s capabilities. Hop in your very own vehicle and use your map to locate all the sick animals in the eucalyptus forest, the vast plains or the mountains.' FROM games WHERE igdb_id = 47977 ON CONFLICT (game_id, language_code) DO NOTHING;
