INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darts Wii DX', 'Enjoy authentic darts with Darts Wii DX. Grasp the Wii remote by holding the darts arrow and swing the Wii remote toward the screen. You can experience a realistic darts game like throwing darts. The game has five modes: zero one, cricket, cut throat, count up, and rotation. In addition, there is a free throw mode where you can practice freely. Nintendo Wi-Fi connection allows you to participation and browsing of national ranking.' FROM games WHERE igdb_id = 268121 ON CONFLICT (game_id, language_code) DO NOTHING;
