INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dolphin Island: Underwater Adventures', 'With Dolphin Island: Underwater Adventures, be ready to travel the world to save and take care of endangered marine animal species and preserve underwater treasures! Greg and Mila take board on the Delphis, an amazing submarine boat that will lead them on a fabulous journey around the seas and oceans of the world. Their mission is to watch out for endangered animals and collect valuable information. The more information they get, the better equipped they will be to protect the marine environment.' FROM games WHERE igdb_id = 122510 ON CONFLICT (game_id, language_code) DO NOTHING;
