INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anti-Idle: The Game', 'Idle Game created by Tukkun and playable exclusively on Kongregate, first released in 2009. The game follows standard idle game rules but also incorporates several elements from other types of games into one game. It actually lets you toggle whether you are idle or not - if you aren''t idle, not only will you get the rewards from playing whatever part of the active game you''re playing, you''ll also get more rewards than if you just left it on idle.' FROM games WHERE igdb_id = 225644 ON CONFLICT (game_id, language_code) DO NOTHING;
