INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arctic Flyer', 'A game from 2009 that was distributed with Nestles Cereals. In the game the player controls a plane based on an Cessna 185 Skywagon. Embark on an arctic mission and photograph wildlife. Maneuver the plane through the Arctic wilderness and take good photos to document the wildlife for scientists. Every photo counts, so use film wisely.' FROM games WHERE igdb_id = 318376 ON CONFLICT (game_id, language_code) DO NOTHING;
