INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Speed Zone', 'A futuristic racing game for the Wii home video game system. Players can choose from three modes of play: Solo, Race, and Battle. In Race mode, players compete against seven computer-controlled AI cars, while Battle mode is an all-out, futuristic demolition derby, using spectacular weapon. In Solo mode, players try to ignite jet thrusters with boost pads to accelerate "into the zone," with phantom cars and racing lines to help set lap records.' FROM games WHERE igdb_id = 51130 ON CONFLICT (game_id, language_code) DO NOTHING;
