INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cook Wars', 'The fun never ends with over 30 mini-games of cooking challenges, offering a wide variety of gameplay: grill, cook, bake, cut, roll in numerous recipes from the world''s best cuisines. Compete to become the best cook and win as you make some of the best international foods from 5 countries (Mexico, USA, France, Italy, Asia). Multi-player functions, including 2 players vs. 2 players or 3 players vs. 1 player as well as an intense duel mode, offer the whole family a chance to play together. Unlock new ingredients and star chefs as you progress through the different modes.' FROM games WHERE igdb_id = 50941 ON CONFLICT (game_id, language_code) DO NOTHING;
