INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shifter''s Box: Outside In', 'Sally is taking a walk outside one fine day when she comes across a strange box. Curious as to who would leave such a strange box lying around, she opens it - only to find herself in a very strange place indeed. Help Sally uncover the true nature of the box and find her way home!' FROM games WHERE igdb_id = 171777 ON CONFLICT (game_id, language_code) DO NOTHING;
