INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magical Drop Yurutto', 'A downloadable Magical Drop for DSi, released only in Japan. "Magical Drop Yuruto" is a game that has two modes: "Magical Drop", which erases colorful drops coming down from above side by side, and "Yuruyuru Yuruto", which allows you to fortune-telling with tarot cards. With the cute characters of "Yuruyuru Friends" designed by Toshinao Aoki, you can play with the magical drop of comfortable operation with the touch pen, and have the tarot card "loosely" fortune.' FROM games WHERE igdb_id = 67846 ON CONFLICT (game_id, language_code) DO NOTHING;
