INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('itzabitza', 16108, '2009-09-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/e9jsegmzmskjnmcsqesl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/oxgxzxnncelkcnrjdi2h.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ItzaBitza', 'In the award winning game ItzaBitza , drawings truly come to life.   Kids help their Sketchy by using Living Ink - a unique drawing recognition system – to draw one-of-a kind interactive objects that form the centerpiece of the game''s action.   Draw a house and watch the character shrink to fit in the door; draw flames and watch the rocket ship they drew blast off.    The game provides a totally unique experience every time it is played. Since the environment is created through each player''s personal drawings, the possibilities are as endless and fantastic as the player’s imagination.  The game comes with five themed playsets – "Home Sweet Home", "Let’s go Camping", "Play in Space", "A Farm Life", and perfect for Halloween – "A VERY Scary Haunted House."  Players unlock playsets by winning star challenges.  ItzaBitza is more than just a fun game.  The game has been crafted specifically for early-readers.  In ItzaBitza, players who are just learning to read start out having a blast watching the whimsical reactions happen between their drawings and their Sketchy.  Then all of a sudden, they need to read to win a star.  Or to know what to draw so they can help their Sketchy.   Parents will be delighted by the game''s ability to enhance their child''s self-confidence. Unlike some games that leave younger players frustrated by their difficulty and lack of assistance, ItzaBitza provides features to guide children even when faced with unfamiliar concepts. If an early-reader encounters a new word, it can be read aloud to them with the simple act of hovering the mouse over the word.   Through a delightful twist on drawing games, ItzaBitza introduces a new way for kids to game and while they are playing, really important learning is happening.  New methods to engage children, discovered during a multi-year research project conducted by Microsoft Corporation, are fused into the game''s design, yielding a unique experience that encourages fun and learning.' FROM games WHERE igdb_id = 16108 ON CONFLICT (game_id, language_code) DO NOTHING;
