INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evacuation', 'Evacuation is a puzzle game where you try to rescue as many astronauts, so without letting them in a room with aliens or into outerspace. You do this by clicking on the colored doors, on which all doors of the corresponding color also open or close.' FROM games WHERE igdb_id = 182454 ON CONFLICT (game_id, language_code) DO NOTHING;
