INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uwol: Quest for Money', 'Uwol: Quest for Money was originally developed by the Spanish development team, Mojon Twins. Uwol was released for the ZX Spectrum Console and it has been ported to the Genesis by Shiru. Uwol is a really fun game that resembles a lot the 80s and 90s arcades, and also it is "Nintendo hard". Uwol Features 55 Levels where the player needs to find money on a millionaire mansion that is haunted by our classic monsters.' FROM games WHERE igdb_id = 46675 ON CONFLICT (game_id, language_code) DO NOTHING;
