INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shuwa no Mori', 'This educational software for the Nintendo DS is an introductory course in Nihon Shuwa (Japanese Sign Language). Touchscreen vocabulary selection is used to trigger and replay demonstrations, and progress is measured via quizzes. In game points are earned and can be used to "purchase" sign-language picture novels, which can be read by the player. Includes emergency sign language and quick reference tools.' FROM games WHERE igdb_id = 254483 ON CONFLICT (game_id, language_code) DO NOTHING;
