INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '8BallAllstars', '8BallAllstars features authentic tables, challenge mode, track record statistics plus wireless play. With 8 rule sets – US 8 Ball, US 9 Ball, UK 8 Ball, 3 Ball, 6 Ball, 10 Ball, Rotation and Straight Pool – 7 table types and real pool physics, 8BallAllstars give you and your friends your game of pool on the Nintendo DS!' FROM games WHERE igdb_id = 55079 ON CONFLICT (game_id, language_code) DO NOTHING;
