INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire Rescue', 'A game from 2009 that was distributed with Nestles Cereals. In the game the player controls a plane based on an Canadair CL-415 and CL-215. Extinguish wildfires before the entire forest is engulfed in flames. Learn how to fly your firefighting aircraft. Fly low and skim nearby lakes to pick up water, then release it over the fires. Put out all the fires before time runs out to complete the level and save the forest.' FROM games WHERE igdb_id = 318366 ON CONFLICT (game_id, language_code) DO NOTHING;
