INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Squid Yes! Not So Octopus!', 'Born of atomic death! Raised in the shadow of a mushroom cloud! He''s a squid! Not an Octopus! He''s Squid Yes! Not So Octopus! And he''s very irritable. A classic single player, psychedelic, retro styled, arena shooter. The aim of the game is to score as close to 9 as possible whilst not succumbing to the invading masses.' FROM games WHERE igdb_id = 67833 ON CONFLICT (game_id, language_code) DO NOTHING;
