INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doom II RPG', 'Doom II RPG is a first-person shooter role-playing video game, the sequel to Doom RPG. It was released for mobile phones on November 23, 2009 and for iPhones on February 8, 2010. Versions for BlackBerry OS and Windows Mobile are also available. It uses the Wolfenstein RPG engine and was developed by id partners Fountainhead Entertainment via the merger id Mobile. The iPhone version of Doom II RPG contains a digital comic book.' FROM games WHERE igdb_id = 101031 ON CONFLICT (game_id, language_code) DO NOTHING;
