INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Air Drop', 'A game from 2009 that was distributed with Nestles Cereals. In the game the player controls a helicopter based on an Lockheed C-130 Hercules. Distribute medical aid to remote areas in need. Learn how to fly your plane and drop packages on the targets. You get points for accuracy so wait for the right moment to release the cargo.' FROM games WHERE igdb_id = 318369 ON CONFLICT (game_id, language_code) DO NOTHING;
