INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rebirth-of-fortune', 174322, '2009-12-14', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rebirth of Fortune', 'Rebirth of Fortune is a tactical strategy role-playing game with customizable unites! Up to eight of your units battle hoards of mercenaries in turn-based, strategic combat on various terrains. Upgrade and customize your own units to compete in a chess-like strategy game of position and power. Your eight individual units share a mutual relationship and utilize various strategies and skills according to their disposition. A divisive strategy is required to beat each of 200 stages and various enemy AIs. If you eradicate the enemy you will be rewarded, and using the rewards fund you can upgrade your units and prepare for greater combat.' FROM games WHERE igdb_id = 174322 ON CONFLICT (game_id, language_code) DO NOTHING;
