INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mind, Body & Soul: Nutrition Matters', 'Discover just how healthy you really are? Nutrition Matters is perfect if you''re looking for a fun way to maintain a healthy balance between diet and exercise in the comfort of your living room. In fact, you can combine nutrition matters with your fitness game of choice for all round well-being. Use your Wii as your personal nutrition monitor to easily track your calories and measure them against daily activities in order to reach your personal fitness goals.' FROM games WHERE igdb_id = 209013 ON CONFLICT (game_id, language_code) DO NOTHING;
