INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kupu!! Mamegoma!', 'The 3rd installment of the "Mamegoma" series, in which you raise seals and Mamegoma that are small enough to fit in your hand, is now available! There are 40 new types of Mamegoma in total! Two Mamegoma can be raised together, and you can pet them, tickle them, and touch them with a stylus. Items such as rice and interior items are also available, and there are 180 cosplay items that can be worn by Mamegoma. Also, when you play music to Mamegoma, they will remember the song and hum with a cute cry.' FROM games WHERE igdb_id = 67742 ON CONFLICT (game_id, language_code) DO NOTHING;
