INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aveyond 3: Orbs of Magic - Chapter 1: Lord of Twilight', 'Chapter 1 in a four-part series! Journey across a massive world on a quest to thwart a power-crazed lunatic who wants to enslave humanity! Two hundred years ago, a sorcerer attempted to fulfill a dark prophecy that would see him rule the world. He died before his goal was realized, but the prophecy' FROM games WHERE igdb_id = 10012 ON CONFLICT (game_id, language_code) DO NOTHING;
