INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marker Man Adventures', 'It was just an ordinary day in the life of Marker Man, the loveable stick figure, and his pal Doodle Dog. That all ended abruptly, however, when Doodle went missing without a trace. Guide Marker Man through hundreds of physics based puzzles using your stylus as a creative tool to safely bring Doodle Dog home!' FROM games WHERE igdb_id = 47843 ON CONFLICT (game_id, language_code) DO NOTHING;
