INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boxgame', 'In the three-dimensional world of Boxgame, it’s hard to know which way is up. As you walk and jump around the perimeter of the game’s giant translucent boxes, floors can become walls, walls can become ceilings, and players will become disoriented.' FROM games WHERE igdb_id = 242919 ON CONFLICT (game_id, language_code) DO NOTHING;
