INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nanako-descends-to-hell', 39151, '2009-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co87zr.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nanako Descends to Hell', 'Controlarás a Nanako en el Infierno buscando los cuatro trozos del artefacto ese. El maldito Infierno se te presentará usando una perspectiva cenital. Podrás mover a Nanako en las cuatro direcciones, guardándote de darte una morrada contra los enemigos que pululan por ahí con el baile de san Vito (de todos es conocido que no hay servicios públicos en el Infierno; de hecho el Martirio Infernal se reduce a que no puedes ir a mear en toda la eternidad – según la doctrina de Vah-Ka). Además, a lo largo del juego encontrarás otros objetos (además de los cuatro trozos del artefacto) que te serán necesarios en tu aventura: Agua bendita: Portando un frasco de agua bendita hará que la próxima morrada contra un enemigo no nos reste una vida. Cizallas: Las cizallas sirven para abrirse paso a través de las rejas metálicas. Para usarlas, colócate junto a la verja y pulsa la dirección en la que esté junto con FIRE. Hacha: El hacha sirve para abrirse paso a través de los árboles. Se emplea de la misma forma que las cizallas, colocándose junto al árbol y pulsando la dirección en la que esté junto con FIRE. Nanako sólo puede llevar 4 objetos. A la hora de cogerlos, veremos como se van desplazando cíclicamente entre nuestro enventario y el contenedor de objetos de donde los estamos cogiendo. Para finalizar nuestra misión con éxito, hay que conseguir los cuatro trozos del artefacto y volver a la pantalla inicial, donde empezamos la partida.' FROM games WHERE igdb_id = 39151 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 39151 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
