INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taiko no Tatsujin 13', 'The 13th Taiko no Tatsujin, released on December 2009 just five months after the wildly successful Taiko 12.5. Taiko 13 takes the game to new heights, being the first version to be used in a nationwide (Japan, of course) official Taiko no Tatsujin tournament in April 2010. In terms of new features, again it doesn''t introduce many new things, except a slight change in the Children/Folk genre name from Kanji to hiragana.' FROM games WHERE igdb_id = 294220 ON CONFLICT (game_id, language_code) DO NOTHING;
