INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chickhack', 'You are a young chick warrior from your village. A terrible drought has caused all your village''s crops to dry up, and there is a risk of famine! So, your village elder asked you to search for the fabled Sacred Grove in the distant mountains, where the Seed of Life is rumored to lie.  The ? key will display help for you in the game!  This game was Purpleflayer''s entry for the 2009 7DRL programming challenge' FROM games WHERE igdb_id = 41169 ON CONFLICT (game_id, language_code) DO NOTHING;
