INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spin Doctor', 'How many levels can you survive in this addictive retro arcade game? Can you swing your wand past a field of deadly spikes, fuses, and acid droplets to move to the next level? As you progress, the field gets tougher and the levels get trickier. Have fun but STAY ALERT! Your wand never stops spinning as you fight towards the finish! Can you do it?' FROM games WHERE igdb_id = 175389 ON CONFLICT (game_id, language_code) DO NOTHING;
