INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Desert Nightmare', 'Taking place somewhere in California, the game follows Sandra Richmont, who was traveling with her parents to visit their uncle. After an argument and a bathroom stop, her parents appear to have driven off without her. Thinking that her parents plan to stay overnight in the nearest city, Dusty Creek, Sandra heads towards there. However, after meeting two others who are stranded, she realizes that they are trapped and the city has some dark secrets...' FROM games WHERE igdb_id = 131034 ON CONFLICT (game_id, language_code) DO NOTHING;
