INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Irukandji', 'Irukandji is a fun score attack shooter, set in an abstract underwater trench. You fly your ship against the flow of hundreds of amazing procedurally animated sea monsters, blasting your way to the final showdown – a Giant Enemy Crab! As you play, you unlock a variety of different ships each with its own unique weaponry and play style which offers a different way to play the game. There are also 10 challenging achievements to attempt, and online scores for each ship.' FROM games WHERE igdb_id = 10461 ON CONFLICT (game_id, language_code) DO NOTHING;
