INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cabela''s Outdoor Adventures', 'The game features North America''s top outdoor destinations, over 50 hunting and fishing adventures and intensive use of gear and tactics, such as animal calls and stealth skills. Emphasis is placed on moments that are instinctively associated with hunting and fishing, like deer stalking, squeezing the trigger, hooking a fish or snap-shooting a flushed bird, all while respecting real life hunting rules and regulations.' FROM games WHERE igdb_id = 91390 ON CONFLICT (game_id, language_code) DO NOTHING;
