INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Leaf Trombone: World Stage', 'Leaf Trombone World Stage is an instrument, a game, and a huge global social experience. You can blow into your iPhone, or use touch mode with iPod touch to make beautiful music. It''s that easy! You can practice your favorite songs as much as you like. Then when you feel ready, strut your stuff by performing on the World Stage, Smule''s revolutionary new platform where Leaf Trombone lovers around the world can listen to and score your playing. Leaf Trombone was discontinued in April 2012.' FROM games WHERE igdb_id = 253762 ON CONFLICT (game_id, language_code) DO NOTHING;
