INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('galileo-mystery-the-crown-of-midas', 268118, '2009-10-22', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galileo Mystery: The Crown of Midas', 'Stephan took a job as a night watchmen in a museum, but the adventure of his life begins just a few minutes after he arrives! A mysterious boss, cryptic exhibits and dangerous intruders; he will need all his wits about him if he and his friend Jessica are to make it through the night… Features: •Detailed environment in a mysterious museum with several different locations •Exiting story with tricky puzzles •Play both Stephan and Jessica and combine the actions of both to solve puzzles •Several minigames loosen up the typical explore-and-answer-questions-experience of adventure games (rebuild a dinosaur skeleton, chess-like game with queens only, pointing/balancing game with mirror) •A built-in help system will enable the player to finish the game completely instead of getting lost and frustrated halfway through the game' FROM games WHERE igdb_id = 268118 ON CONFLICT (game_id, language_code) DO NOTHING;
