INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eve Online: Special Edition', 'A collection of all ten free updates to EVE Online, up to early 2009''s Apocrypha expansion. The Special Edition includes: - Exclusive digital Career Guide, roughly equivalent to a hint book (giving goals and suggestions for careers and playing the economy) - 60 days of free game time, and a VIP code for 30 more days if a friend also subscribes. - Brand new accounts also receive an exclusive ship - Certificate for instant access to the factional warfare system' FROM games WHERE igdb_id = 329788 ON CONFLICT (game_id, language_code) DO NOTHING;
