INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gamma IV', 'Gamma IV plays like the laser show of a Daft Punk concert, with electro-heavy beats and a pulsing spectrum of coloured beams, similar to the waves of audio visualization applications. The game is split up in different scenes with progressive difficulty and a single music track in the background, bridging all scenes.' FROM games WHERE igdb_id = 199154 ON CONFLICT (game_id, language_code) DO NOTHING;
