INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cartoon Wars', 'Cartoon Wars is a tower defence game, where you have a castle and different kinds of units you can send out. In every level there is an opposing castle on the other side of the map that sends out enemies and that you have to destroy to win the level. Between levels you can upgrade your units and unlock new ones by spending gold and gems earned through the levels.' FROM games WHERE igdb_id = 230784 ON CONFLICT (game_id, language_code) DO NOTHING;
