INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3Scapes', '3Scapes is a text-based multi-user dungeon. Communication across the dimensions is easily handled, as is the ability to retain your character identity (i.e. name) across all existence, but beyond that, everything else is unique. Since opening in 2009, 3Scapes has grown to become a virtual community of over 800 characters with new guilds, new areas, new quests, and new functionality. With its own cast of players, administrators, and its own unique feel, 3Scapes is a vibrant virtual world ready for you to visit, explore, and enjoy!' FROM games WHERE igdb_id = 228798 ON CONFLICT (game_id, language_code) DO NOTHING;
