INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ultimate-party-challenge', 51059, '2009-12-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/pg4ifbsqeqv5vzzlrch7.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate Party Challenge', 'Get ready to challenge your friends and family in the Ultimate Party Challenge!  Family fun for everyone! It’s time to get the party started this Holiday with Ultimate Party Challenge on Wii. Play tons of high energy, over-the-top competitions, wacky sports activities, and mind boggling brain challenges! Get your body moving with the innovative use of the DanceDanceRevolution Controller and Wii Remote. Test your skills in a world of colorful, interactive backdrops and tons of multiplayer games for you and up to 3 of your friends! Get on your feet and jump into the Ultimate Party Challenge!  Features  • Compete in 40 fun minigames that test your physical, musical, and mental skills  • Customize your very own avatar or choose from a diverse selection of amusing characters  • Move your body by using your DanceDanceRevolution controller and Wii Remote  • Select from a variety of multiplayer Modes where you can play with up to 3 of your friends  • Test your rhythm, speed, and brain skills in a collection of fantasy games and crazy sports events, such as:  • Bungee Splash  • 3-Row Free Throw (Basketball)  • Balloon Race  • Pinball  • Human Cannonball  • Snowboard Challenge  • Cow Coral Roundup, and more!  • Win minigame challenges to unlock new accessories in the Party Shop and dress your character in new outfits  • Enjoy colorful 3D backgrounds and high-energy music in every level' FROM games WHERE igdb_id = 51059 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 51059 AND p.igdb_id = 5 ON CONFLICT DO NOTHING;
