INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aliens in the Attic', 'Aliens in the Attics for the Wii, PlayStation 2 and PC versions give players a whole new way to experience the story by assuming the identity of different alien explorers whose motives are to rid of the house guests so they can take over the mansion and possibly the world. Players will experience 15 exciting levels, four locations, and switch between players for fast paced action.' FROM games WHERE igdb_id = 50970 ON CONFLICT (game_id, language_code) DO NOTHING;
