INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Imp or Oaf?', 'Do you think you know the difference between an Imp and an Oaf? In this game you''re given a glimpse into the odd world of these bizarre creatures and you must take a guess at what you think you''re looking at: Is it an IMP or an OAF?! You can tap the picture to zoom out and see more, this will help you make a better guess but you''ll get fewer points!' FROM games WHERE igdb_id = 254259 ON CONFLICT (game_id, language_code) DO NOTHING;
