INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Treasure Treasure: Fortress Forage', 'Trixie and Troy need to combine their talents, think carefully and blow things up to find all the treasures hidden in an abandoned castle. This is a two player split-screen puzzle/platform game, with local co-op only. You can use two joypads if you have them, but snuggling together on one keyboard is just as fun. The castle is pretty maze-like so there’s plenty of exploration to be done too.' FROM games WHERE igdb_id = 91780 ON CONFLICT (game_id, language_code) DO NOTHING;
