INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inugamike no Ichizoku', 'A mystery visual novel by FromSoftware, starring the famous Japanese detective Kindaichi Kousuke. In 1940s Japan, the wealthy head of the Inugami Clan dies, setting off a chain of bizarre, gruesome murders. Detective Kindaichi must unravel the clan’s terrible secrets of forbidden liaisons, monstrous cruelty, and disguised identities to find the murderer.' FROM games WHERE igdb_id = 130701 ON CONFLICT (game_id, language_code) DO NOTHING;
