INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anka', 'Anka lives a peaceful life with his parents but one day his mother doesn’t come back from town after running some errands. Soon afterwards his father disappears too. Bravely, the resourceful Anka sets off to find them by himself. Unveil a charming point and click Adventure game as you tackle perplexing puzzles and challenges ranging from logic brainteasers to games of skill. Help young Anka find his family!' FROM games WHERE igdb_id = 22122 ON CONFLICT (game_id, language_code) DO NOTHING;
