INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skies of Glory', 'Gear up for the ultimate in multiplayer air combat! Skies of Glory takes you back to the groundbreaking aeronautics of World War II, set in the real life terrain of both Pacific and European theatres of war. Over land and sea, under realistic weather conditions, you and your friends can team up to defend a base, destroy enemy compounds and logistical resources, or show off your piloting skills in a full-force free-for-all.' FROM games WHERE igdb_id = 62446 ON CONFLICT (game_id, language_code) DO NOTHING;
