INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dreamer Series: Pop Star', 'Become a sensational pop star and travel the globe with your spectacular performances. Sing, play guitar, drums and keyboard as you take your band to the top of the charts! Go solo or jam with your friends – the choice is yours! Features: • Choose your very own band name! • Determine your band’s unique look – outfits, instruments and more! • Sing, play the guitar, drums and keyboard – It’s your band, you do what you want! • No additional peripherals required. • Play solo or jam along with your friends!' FROM games WHERE igdb_id = 47906 ON CONFLICT (game_id, language_code) DO NOTHING;
