INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DS Uranai Seikatsu', 'DS Uranai Seikatsu (literally DS Divination Life) is a divination game for Nintendo DS, released in Japan as part of the Touch! Generations line in 2009 . DS Uranai Seikatsu allows players to partake in multiple divination exercises and techniques, which include tarot readings, palmistry, the Four Pillars of Destiny, Zi Wei Dou Shu, horoscopes, Da Liu Ren and a daily fortune message.' FROM games WHERE igdb_id = 265904 ON CONFLICT (game_id, language_code) DO NOTHING;
