INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1500 DS Spirits: Mahjong V', '1500DS Spirits: Mahjong V (widely used English translation. Original name is "1500 DS spirits: 麻雀V") is a Japan exclusive mahjong game. It is part of a large series of Nintendo DS titles which focus on table games all labeled 1500DS Spirits and created and published by Tasuke Co. Ltd.. This game is a special addition version of 1500DS Spirits: Vol 1 Mahjong and has extra added features compared to that game. This game used 1500DS Spirits: Vol 1 Mahjong as a base for this game so it has some similarities to this game including borrowed modes and assets.' FROM games WHERE igdb_id = 268074 ON CONFLICT (game_id, language_code) DO NOTHING;
