INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warlords', 'A multiplayer classic that resurrects the competitive spirit of arcade games from years gone by. Knock out the other kings in their castles while keeping yourself protected at the same time. Up to four players can join the action with the game taking control of any vacant castles allowing for a variety of single- or multiplayer experiences. The Evo mode allows players to import their own pictures to their castles.' FROM games WHERE igdb_id = 294544 ON CONFLICT (game_id, language_code) DO NOTHING;
