INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gary Grigsby''s Eagle Day to Bombing the Reich', 'Gary Grigsby’s Eagle Day to Bombing of the Reich is a detailed simulation of the Allied strategic bombing campaign against Germany in World War II. Combining both classic titles Battle of Britain and Twelve O''clock High into a single game package, this in depth air war simulation includes all the appeal of the original two titles with a huge list of extra features and improvements.' FROM games WHERE igdb_id = 59529 ON CONFLICT (game_id, language_code) DO NOTHING;
