INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Steamshovel Harry', 'Steamshovel Harry is a flash game. You play as Steamshovel Harry who, as part of Near-Earth-Defense force, needs to stop the Paramilitary Asteriod Miners, who have launched a missile towards Earth, from destroying the planet. You have ten minutes.' FROM games WHERE igdb_id = 282809 ON CONFLICT (game_id, language_code) DO NOTHING;
