INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vegas Party', 'The game takes the player into the gambling-friendly universe of this over-the-top version of Las Vegas city. Played as a race, the goal is to reach the end of the Strip before anyone else. Manage your token account in 15 gambling minigames, avoid the dangers like twisters and earthquakes, take advantage of your gaming skills and your good luck, trust no one and forget the meaning of the word “mercy” because it does not apply here!' FROM games WHERE igdb_id = 51058 ON CONFLICT (game_id, language_code) DO NOTHING;
