INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eliss', 'Eliss is a puzzle video game developed and published by Steph Thirion. It was released for the iPhone OS on March 6, 2009. Eliss'' gameplay revolves around filling "squeesars" with planets of like color and size. Planets can be combined, split, and moved around using the multi-touch interface. Further complication is added by passing red stars and vortices.' FROM games WHERE igdb_id = 29052 ON CONFLICT (game_id, language_code) DO NOTHING;
