INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil 5: e-Capcom Limited Edition', 'Resident Evil 5: e-Capcom Limited Edition is a Japanese limited edition box set only available for preorder from e-capcom.com for a short time in December 2008. It came in a sealed, black outer case with a barcode sticker, with the following items inside: - Resident Evil 5 - Tricell box which contains the game and a USB memory stick with instructions - BSAA box which contains a BSAA waist pouch - Resident Evil 5 Art Book A Tricell wallet was also bundled with each of the boxes.' FROM games WHERE igdb_id = 145197 ON CONFLICT (game_id, language_code) DO NOTHING;
