INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Christmas Clix', 'Christmas Clix is an indie adventure puzzle RPG. You can help Santa decorate the tree by removing the presents and ornaments that he stacks. When you consecutively connect packages without missing a beat, you get extra points. Collect as many candy canes as you can because when you collect enough, Santa will add a special star to the game that can greatly help you get through a level or just bring some additional fun!' FROM games WHERE igdb_id = 51124 ON CONFLICT (game_id, language_code) DO NOTHING;
