INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bibi Blocksberg: Das gestohlene Hexbuch', 'Bibi Blocksberg has the responsible task of taking her mother''s "all-knowing herbal witch book" to the old witch Mania. On the way to Mania''s house, however, Bibi''s curiosity takes over and she decides to take a short break in the Dark Forest to browse through the book. Bibi has no idea that the evil witch Malicia is watching her through her witch''s ball and now senses her chance to finally get hold of the witch book.' FROM games WHERE igdb_id = 215850 ON CONFLICT (game_id, language_code) DO NOTHING;
