INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster 4x4: Stunt Racer', 'Monster 4x4: Stunt Racer picks up where Monster 4x4: World Circuit finished and delivers bigger wheels, faster trucks and crazier stunts. But this time, there''s an extra twist: an exclusive wall-driving feature. Players will be able to perform vertical stunts and find shortcuts as they take on their friends and family in 4-player split screen modes.' FROM games WHERE igdb_id = 50958 ON CONFLICT (game_id, language_code) DO NOTHING;
