INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Korogashi Puzzle Katamari Damacy', 'Korogashi Puzzle Katamari Damacy is a falling block puzzle video game released by Namco Bandai for the Nintendo DSi''s DSiWare digital download service for 500 points (5 dollars). It is a spin-off of the Katamari series. However, it bears little resemblance to the series, resembling Tetris more so. It uses the gameplay engine and concept of Pac-Attack, another puzzle game created by Namco.' FROM games WHERE igdb_id = 6458 ON CONFLICT (game_id, language_code) DO NOTHING;
