INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Body Coach', 'Stressed? Feel like losing a few extra pounds? Don''t have enough time to go to the gym? Then buy this game and get the body you''ve always dreamed of without leaving your room! A sports and diet programme developed by Valerie Orsoni that is completely customizable (physical criteria, availability and goals) More than 100 aerobic and muscle-toning exercises: Low and High impact Aerobic, Arms/Shoulders/Bust/Legs/Abs/Gluts and Total Body Conditioning. A fitness encyclopedia so you can exercise properly. Complete coaching or on-demand sports sessions.' FROM games WHERE igdb_id = 67354 ON CONFLICT (game_id, language_code) DO NOTHING;
