INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tug Team Tractor Multiplication', 'It''s time for a game of tug-of-war with tractors. Tug Team Tractor Multiplication is a free math game for kids. Teams play together to pull the other team across the line. Each correct answer gives the team a tug. The team that pulls the other team over the line wins!' FROM games WHERE igdb_id = 312639 ON CONFLICT (game_id, language_code) DO NOTHING;
