INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The 15th Floor', 'Built by a team of adventure-game lovers, The Fifteenth Floor is an adventure game featuring original character art, 3D models, and music. The game (developed by MindWave) has been 5 months into production, and is nearing completion. It has been inspired by games such as Myst, Crimson Room and Phoenix Wright.' FROM games WHERE igdb_id = 287466 ON CONFLICT (game_id, language_code) DO NOTHING;
