INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crimson Room: Reverse', 'Crimson Room: Reverse''s premise is that the player finds themselves trapped in a single room. Controlling a cursor that can click on items to search and investigate, it''s up to the player to scan the environment for helpful objects and figure out how to use them. The ultimate goal is unlocking an exit door and earning freedom.' FROM games WHERE igdb_id = 67281 ON CONFLICT (game_id, language_code) DO NOTHING;
