INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baby Shaker', 'Baby Shaker was a controversial iOS game released on April 20th, 2009, where you shake your iPhone to stop a crying infant until two X marks appear on their eyes. The game was pulled from the App Store two days later, after it was noticed by the review site KRAPPS and later picked up by other news sources and non-governmental organizations related to Shaken Baby Syndrome who were outraged, with a spokesperson from Apple stating that "this application was deeply offensive and should not have been approved for distribution on the App Store".' FROM games WHERE igdb_id = 256812 ON CONFLICT (game_id, language_code) DO NOTHING;
