INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiger Woods PGA Tour', 'Play the only iPhone/iPod touch game that lets you golf AS OR AGAINST Tiger Woods! Beat Tiger at his own game and step onto legendary courses around the world! Watch each fairway come to life with 3D graphics, dynamic camera angles, and realistic sounds. Take on other PGA pros and hear play-by-play commentary by Sam Torrance and Kelly Tilghman. Use the Swing Meter and get visual feedback to help you achieve the perfect swing! Tee it up with Tiger Woods PGA TOUR by EA Sports - anytime, anywhere!' FROM games WHERE igdb_id = 288021 ON CONFLICT (game_id, language_code) DO NOTHING;
