INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '5 Minutes to Kill Yourself', 'Stan is in hell. He lives the day-in, day-out workaday life of a cube jockey. A last-minute meeting request pushes him over the edge. As Stan, you wander the office space finding ingenious ways to hurt him until Stan''s health is completely drained. He has but five minutes—if he can''t do it by then, he''s doomed to sit through yet another boring meeting. You''re Stan''s only hope.' FROM games WHERE igdb_id = 92375 ON CONFLICT (game_id, language_code) DO NOTHING;
