INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Higurashi no Naku Koro ni Jan', 'Higurashi no Naku Koro ni Jan is a spin-off on the Higurashi no Naku Koro ni franchise with the characters competing with each other in a popular Japanese board game mahjong. The game features traditional Riichi Mahjong rules, which are customizable, however, unlike normal Mahjong, this mahjong game is a one-on-one battle, as opposed to the usual 4 players. The story is told through NVL segments interspersed with Mahjong minigames.' FROM games WHERE igdb_id = 229816 ON CONFLICT (game_id, language_code) DO NOTHING;
