INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Mother', 'Touhou Mother is a Touhou Project and EarthBound cross-over parody RPG game. It stars Reimu Hakurei, Marisa Kirisame, Yuuka Kazami and Mima and features many Touhou characters from the PC-98 and Windows canon, along with several characters from the Mother series and a few fan-made characters. The majority of the outside influence and references comes from EarthBound, but other notorious video games are paid homage as well.' FROM games WHERE igdb_id = 184129 ON CONFLICT (game_id, language_code) DO NOTHING;
