INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dice Dice Fantasia', 'Dice Dice Fantasia is a Miscellaneous game, developed and published by Broccoli, which was released in Japan in 2009. ``Yuhodo,'''' which handles systems for numerous card games, is in charge of system design. It''s a simple yet deep board game with lots of elements to play with. In addition, Munetsugu Kusaka, who works on illustrations for light novels and bishoujo games, has been appointed as the character designer and original artist. The theme song will be delivered by a lineup with Elements Garden producing the music and Haruka Shimotsuki on vocals!' FROM games WHERE igdb_id = 278826 ON CONFLICT (game_id, language_code) DO NOTHING;
