INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cooking Academy 2: World Cuisine', 'Cooking Academy 2 is the second entry in a cooking simulator series. The goal remains the same, the player has to use the mouse to slice and dice vegetables and meat on the chopping board, liquefy ingredients in the food processor, and perform other common kitchen activities before the timer at the top-right corner reaches zero.' FROM games WHERE igdb_id = 208483 ON CONFLICT (game_id, language_code) DO NOTHING;
