INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Medieval Games', 'Battle dragons! Storm castles! Swordfight! Relive the days of olde in this fun collection of 30 medieval-inspired mini games and tournament championships set in a charming storybook world. Featuring easy pick up and play action, light hearted humor and support for up to four players, Medieval Games is sure to be a family favorite.' FROM games WHERE igdb_id = 5001 ON CONFLICT (game_id, language_code) DO NOTHING;
