INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jacqueline Wilson''s Tracy Beaker: The Game', 'You can become the star of Tracy Beaker the Game. Enjoy the super-cool challenge of playing Tracy as you guide her through a tip top adventure story based on the terrific characters created by Jaqueline Wilson. Explore 11 totally fantastic environments including the Dumping Ground, Tracy''s school and Cam''s house - chat to all the characters, solve the puzzles and look out for items to collect! As brace and brilliant Tracy Beaker, only you can decide the outcome... will she live happily ever after or have to face the consequences? It''s up to you!' FROM games WHERE igdb_id = 67562 ON CONFLICT (game_id, language_code) DO NOTHING;
