INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chou Aniki Zero', 'Cho Aniki Zero brings manliness back to the old-school shoot-em-up genre and, warps it to another dimension of sights and sounds. In Cho Aniki Zero, players will be introduced to brand-new characters and newly heightened experiences of rhythmic action, intertwined with the famous BGM of Kouji Hayama. Battle through five man-rageous levels of brotherly love and muscle-on-muscle madness!' FROM games WHERE igdb_id = 42859 ON CONFLICT (game_id, language_code) DO NOTHING;
