INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cross Fingers', 'Mobigame, the team behind the multiple award winning EDGE, Perfect Cell and Zombie Tsunami returns in full force with Cross Fingers, a unique game which challenges you to combine solid pieces in a gigantic tangram puzzle. You will need to exercise your brain, imagination and - unique for a puzzle game - your reflexes and dexterity to complete all 840 levels! For unlimited replay value, unlock the Arcade Mode, which puts you in the middle of a frenetic machine where the challenge is to survive and beat the top score.' FROM games WHERE igdb_id = 232300 ON CONFLICT (game_id, language_code) DO NOTHING;
