INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man Rush Marine', 'Take the plunge with Mega Man and his shape-shifting robot dog, Rush in this original side scrolling shooter set in the deep blue sea. In the year 20XX Dr. Wily sends his robot minions to the seabed in order to drill for oil causing earthquakes and destruction to the surrounding islands. Only Mega Man and the newly submersible Rush Marine have any hope of stopping Wily’s nefarious plan.' FROM games WHERE igdb_id = 290981 ON CONFLICT (game_id, language_code) DO NOTHING;
