INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Labyrinth of Touhou', 'Touhou no Meikyuu, also known as Touhou Labyrinth, is a fan-made Touhou Project-centric dungeon crawler with similarities to titles such as Wizardry or Etrian Odyssey. A large cast of Touhou characters are included, as well as a number of references and cameos of other role-playing, anime, and danmaku titles. A sequel, Labyrinth of Touhou 2 was released at Comiket 84.' FROM games WHERE igdb_id = 63855 ON CONFLICT (game_id, language_code) DO NOTHING;
