INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ponjan Wii', 'The board game Ponjan Wii adapts the rules of Mahjong simply for WiiWare. The rule is that participating players will only exchange one of the nine tiles in order with the tiles in the mountain. The player who achieves 3 "sets" consisting of the same 3 tiles first will be the winner.' FROM games WHERE igdb_id = 142692 ON CONFLICT (game_id, language_code) DO NOTHING;
