INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mystery-pi-the-new-york-fortune', 14814, '2009-01-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob3cj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/p0qcvsf71q7okb8grajq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mystery P.I. - The New York Fortune', 'A fun loving & eccentric New York billionaire has hidden the will to his vast fortune somewhere in New York City! His family only has 17 hours to locate the will or their Grandpa''s entire estate will be given to his cat and dog. You are the world famous Mystery P.I. and the family has hired you to track down the clues hidden all over NYC. Seek & Find over 2100 hidden objects in 25 amazing NY locations like Times Square, Central Park, Coney Island, the Brooklyn Bridge and many more. If you succeed you will be awarded $25 Million dollars. Three addictive ways to play: In NY Fortune mode you must find the clues to locate the will. Collect all the Keys & Apples to unlock two Unlimited game modes: Unlock Unlimited Seek & Find and Spot the Differences to find every hidden item in every scene.' FROM games WHERE igdb_id = 14814 ON CONFLICT (game_id, language_code) DO NOTHING;
