INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Army Rescue', 'We are at war, soldier! We must infiltrate the enemy base in order to rescue our beloved king! Take the ultimate leap and command your forces to victory! Army Rescue is an action-puzzle game fit for all ages and gamers. Put your reflexes and hand-eye coordination skills to the ultimate test: Accurately time, cut and catch your soldiers while evading enemy fire and destroying your adversaries.' FROM games WHERE igdb_id = 51011 ON CONFLICT (game_id, language_code) DO NOTHING;
