INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Loong: The Power of the Dragon', 'Discover one of the greatest ancient civilizations, created by the mythical god Pangu. Explore the mysteries surrounding the nine regions in your search for the legendary dragons. Re-write the story and become a legend by beating yourself through the darkest dungeons, fighting incredible creatures to gain breathtaking strengths.' FROM games WHERE igdb_id = 23526 ON CONFLICT (game_id, language_code) DO NOTHING;
