INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Youda Farmer', 'Experience true country life when you run your farm, grow your crops and see your business grow as you provide all shops in town with self made farm products! Grow wheat, tomatoes, potatoes and grapes while you take care of your cattle and catch fish. New machinery will help you increase productivity and take care of the farm animals. Will you spend your hard earned money on new crops, a chicken coop or will you build a stable for your sheep?' FROM games WHERE igdb_id = 9315 ON CONFLICT (game_id, language_code) DO NOTHING;
