INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hooked! Again: Real Motion Fishing', 'Players once again cast, hook, and fight fish as they use their Wii Remote to reel in the big one in Hooked! Again, the sequel to Hooked! Real Motion Fishing. The action takes place on a number of fictional lakes across three modes of play: Practice, Time Attack, and Tournament. Players can also challenge up to three friends online via the Wii''s Wi-Fi connection.' FROM games WHERE igdb_id = 50627 ON CONFLICT (game_id, language_code) DO NOTHING;
