INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Party Pigs: Farmyard Games', 'The Wildest Pig Contest in Town! The Annual Party Pigs Track & Field competition is about to begin! Dust off your cleats and get ready to compete in zany versions of seven different track & field events. Choose your favorite pig athlete and take on hurdles, swimming, long jump and more. Progress through the tournament or challenge your friends to see who is the greatest athlete at the farm!' FROM games WHERE igdb_id = 51109 ON CONFLICT (game_id, language_code) DO NOTHING;
