INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Love Beauty: Hollywood Makeover', 'In I Love Beauty: Hollywood Makeover players style the stars as they select the most stunning outfits, accessories, and the perfect makeup for all of the glamorous events around Hollywood. With 36 different cosmetics to mix and match in more than 60 variations, I Love Beauty: Hollywood Makeover will test the "fashion eye" of even the most creative stylist and is just the thing for girls who like to have fun and look their best.' FROM games WHERE igdb_id = 47849 ON CONFLICT (game_id, language_code) DO NOTHING;
